let classArchiveView=false,workClass='',workTab='sessions';
function validateClassLearning(v){if(!v||typeof v!=='object'||!Array.isArray(v.items)||!Array.isArray(v.sessions)||v.items.length>50||v.sessions.length>500)throw Error('수업 기록 형식 오류');const ids=new Set();for(const i of v.items){if(!validId(i.id)||ids.has(i.id)||typeof i.name!=='string'||!i.name.trim()||i.name.length>80||!['score','list','text'].includes(i.type)||!Array.isArray(i.options)||i.options.some(x=>typeof x!=='string'||x.length>80))throw Error('평가 항목 오류');ids.add(i.id)}for(const s of v.sessions){if(!validId(s.id)||typeof s.title!=='string'||s.title.length>120||!/^\d{4}-\d{2}-\d{2}$/.test(s.date)||!Array.isArray(s.studentIds)||s.studentIds.some(x=>!validId(x))||!Array.isArray(s.itemIds)||s.itemIds.some(x=>!ids.has(x))||!s.values||typeof s.values!=='object')throw Error('회차 오류');for(const [sid,values] of Object.entries(s.values)){if(!validId(sid)||!values||typeof values!=='object')throw Error('회차 학생 오류');for(const [iid,value] of Object.entries(values)){const item=v.items.find(x=>x.id===iid);if(!item||typeof value!=='string'||value.length>2000||item.type==='score'&&value!==''&&(!Number.isFinite(Number(value))||Number(value)<0||Number(value)>100)||item.type==='list'&&value!==''&&!item.options.includes(value))throw Error('회차 입력 오류')}}}return JSON.parse(JSON.stringify(v))}
function setClassArchive(value){classArchiveView=value==='archived';drawRows()}
function toggleClassActive(id){const c=db.classes.find(x=>x.id===id);if(!c)return;c.inactive=!c.inactive;save();drawRows()}
function renderClassDirectory(){const all=db.classes.filter(c=>c.kind!=='scheduling'),rows=all.filter(c=>!!c.inactive===classArchiveView&&c.name.includes(query)).sort(compareSchedules);return '<div class="toolbar"><button class="btn '+(!classArchiveView?'':'light')+'" data-click="setClassArchive(\'active\')">운영 중 '+all.filter(c=>!c.inactive).length+'</button><button class="btn '+(classArchiveView?'':'light')+'" data-click="setClassArchive(\'archived\')">비활성화 '+all.filter(c=>c.inactive).length+'</button></div>'+table(['수업명','요일·시간','학생','관리'],rows.map(c=>['<button class="student-link" data-click="openClassWork(\''+c.id+'\')">'+esc(c.name)+'</button>',esc(c.day+' '+c.time+'–'+c.end),currentStudents().filter(s=>s.class===c.name).length+'명',classArchiveView?'<button class="btn light small" data-click="toggleClassActive(\''+c.id+'\')">다시 활성화</button> '+removeBtn('classes',c.id):'<button class="btn light small" data-click="openWeeklyReports(\''+c.id+'\')">주간 리포트</button> <button class="btn light small" data-click="showClassReviewAssignment(\''+c.id+'\')">복습 배정</button> <button class="btn light small" data-click="openClassWork(\''+c.id+'\')">회차·평가 관리</button> <button class="btn light small" data-click="openEditor(\'classes\',\''+c.id+'\')">수정</button> <button class="btn light small" data-click="toggleClassActive(\''+c.id+'\')">비활성화</button>']));}
function classLearning(c){return c.learning||{items:[],sessions:[]}}
function openClassWork(id){workClass=id;workTab='sessions';renderClassWork()}
function setClassWorkTab(tab){workTab=tab;renderClassWork()}
function renderClassWork(){const c=db.classes.find(x=>x.id===workClass);if(!c)return;const d=classLearning(c);$('#modal').innerHTML='<h2>'+esc(c.name)+'</h2><div class="toolbar"><button class="btn light small" data-click="setClassWorkTab(\'sessions\')">회차 관리</button><button class="btn light small" data-click="setClassWorkTab(\'items\')">평가 항목</button><button class="btn light small" data-click="document.getElementById(\'modal\').close()">닫기</button></div><div id="class-work-body"></div>';const body=$('#class-work-body');if(workTab==='items')body.innerHTML='<p>항목은 회차 생성 시 복사됩니다. 이후 추가한 항목은 기존 회차에 자동 추가되지 않습니다.</p>'+d.items.map(i=>'<article class="classrow"><div><strong>'+esc(i.name)+'</strong><small>'+esc({score:'점수 (0~100)',list:'선택형',text:'개별 전달 사항'}[i.type])+'</small></div></article>').join('')+'<form id="item-form" class="fields"><label>평가 항목명<input name="name" required maxlength="80"></label><label>유형<select name="type"><option value="score">점수 (0~100)</option><option value="list">선택형</option><option value="text">텍스트</option></select></label><label>선택형 보기 · 쉼표로 구분<input name="options" placeholder="출석,결석,지각"></label><button class="btn" type="submit">항목 추가</button></form>';else body.innerHTML='<button class="btn small" data-click="createClassSession()">＋ 회차 생성</button>'+d.sessions.slice().reverse().map(s=>'<article class="classrow"><div><strong>'+esc(s.title)+'</strong><small>'+esc(s.date)+' · '+s.studentIds.length+'명 · '+s.itemIds.length+'항목</small></div><button class="btn light small" data-click="openSessionInput(\''+s.id+'\')">일괄 입력</button></article>').join('');if($('#item-form'))$('#item-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim(),type=String(f.get('type')),opts=String(f.get('options')).split(',').map(x=>x.trim()).filter(Boolean);if(type==='list'&&!opts.length)return toast('선택형 보기를 입력하세요');c.learning=classLearning(c);c.learning.items.push({id:uid(),name,type,options:type==='list'?[...new Set(opts)]:[]});save();renderClassWork()};$('#modal').showModal()}
function createClassSession(){const c=db.classes.find(x=>x.id===workClass);if(!c||c.inactive)return toast('비활성 수업은 회차를 추가할 수 없습니다');const d=classLearning(c);if(!d.items.length){workTab='items';renderClassWork();return toast('평가 항목을 먼저 추가하세요')}$('#class-work-body').innerHTML='<form id="session-form" class="fields"><label>회차명<input name="title" maxlength="120" required value="'+(d.sessions.length+1)+'회차"></label><label>수업일<input name="date" type="date" required value="'+today()+'"></label><p>현재 수강생과 평가 항목을 이 회차에 저장합니다. 이후 수강생 배정이 바뀌어도 기존 기록은 유지됩니다.</p><button class="btn" type="submit">회차 생성</button></form>';$('#session-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);c.learning=d;d.sessions.push({id:uid(),title:String(f.get('title')).trim(),date:String(f.get('date')),studentIds:currentStudents().filter(s=>s.class===c.name).map(s=>s.id),itemIds:d.items.map(i=>i.id),values:{}});save();renderClassWork()}}
function openSessionInput(id){const c=db.classes.find(x=>x.id===workClass),d=classLearning(c),s=d.sessions.find(x=>x.id===id);if(!s)return;const items=s.itemIds.map(id=>d.items.find(i=>i.id===id));const control=(i,value,name)=>i.type==='list'?'<select '+name+'><option value="">미입력</option>'+i.options.map(o=>'<option '+(value===o?'selected':'')+'>'+esc(o)+'</option>').join('')+'</select>':'<input '+name+' type="'+(i.type==='score'?'number':'text')+'" '+(i.type==='score'?'min="0" max="100" step="0.1"':'maxlength="2000"')+' value="'+esc(value||'')+'">';$('#class-work-body').innerHTML='<h3>'+esc(s.title)+' · '+esc(s.date)+'</h3><p>Tab으로 이동하며 입력할 수 있습니다. 저장 전에는 기록에 반영되지 않습니다.</p><form id="session-input"><div style="overflow:auto">'+table(['학생',...items.map(i=>esc(i.name))],[['일괄 적용',...items.map(i=>control(i,'','data-bulk="'+i.id+'"'))],...s.studentIds.map(sid=>[esc(student(sid)),...items.map(i=>control(i,s.values[sid]?.[i.id],'data-student="'+sid+'" data-item="'+i.id+'" aria-label="'+esc(student(sid)+' '+i.name)+'"'))])])+'</div><div class="actions"><button class="btn" type="submit">저장</button><button type="button" class="btn light" data-click="setClassWorkTab(\'sessions\')">회차 목록</button></div></form>';for(const input of document.querySelectorAll('[data-bulk]'))input.addEventListener('change',()=>{for(const field of document.querySelectorAll('[data-item="'+input.dataset.bulk+'"]'))field.value=input.value});$('#session-input').onsubmit=e=>{e.preventDefault();const values={};for(const input of document.querySelectorAll('[data-item]')){values[input.dataset.student]??={};values[input.dataset.student][input.dataset.item]=input.value}s.values=values;save();toast('회차 기록을 저장했습니다');renderClassWork()}}

const studentNameCollator=new Intl.Collator('ko-KR',{numeric:true,sensitivity:'base'});
function compareStudentNames(a,b){return ['name','school','nickname','id'].reduce((order,key)=>order||studentNameCollator.compare(String(a[key]||'').normalize('NFC').trim(),String(b[key]||'').normalize('NFC').trim()),0)}
function sortedStudents(items){return [...items].sort(compareStudentNames)}

