const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'});const uid=()=>(crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2));let db,invalidStoredData=false;try{const stored=cloudManagerStorage.getItem('yensense-v1');db=validateDatabase(JSON.parse(stored))}catch{db=cloudManagerEmpty();invalidStoredData=true}let committedState=JSON.stringify(db);let page='dashboard',query='',filter='',attDate=today();const menus=[['dashboard','◫','대시보드'],['students','♙','학생 관리'],['classes','▦','수업 관리'],['attendance','✓','출결 관리'],['tasks','☷','과제 관리'],['scores','▥','성적 관리'],['exams','▤','시험 · 자동 채점'],['videos','▷','복습 영상'],['notes','☏','상담 기록'],['reservations','▦','예약 시스템'],['bookings','▤','클리닉 기록'],['payments','₩','월별 정산'],['notices','♧','공지사항'],['settings','⚙','설정 · 백업']];function save(){if(invalidStoredData)throw new Error('저장된 데이터 검증이 필요합니다. 설정에서 올바른 백업을 복원하세요.');let safe;try{safe=validateDatabase(db);cloudManagerStorage.setItem('yensense-v1',JSON.stringify(safe));committedState=JSON.stringify(safe);if(typeof queueHomeworkSync==='function')queueHomeworkSync();if(typeof queueReviewRosterSync==='function')queueReviewRosterSync()}catch(error){db=JSON.parse(committedState);throw error}}function toast(t){$('#toasts').innerHTML='<div class="toast">'+esc(t)+'</div>';setTimeout(()=>$('#toasts').innerHTML='',2600)}function go(p){if(p==='weekly'&&typeof weeklyState!=='undefined')weeklyState.view='classes';if(location.hash.startsWith('#student/'))history.pushState(null,'',location.pathname+location.search);page=p;query='';filter='';render()}function student(id){return db.students.find(s=>s.id===id)?.name||'삭제된 학생'}function options(items,selected=''){return items.map(x=>'<option '+(x===selected?'selected':'')+'>'+esc(x)+'</option>').join('')}function so(){return sortedStudents(currentStudents()).map(s=>'<option value="'+s.id+'">'+esc(s.name+' · '+s.school)+'</option>').join('')}function classOptions(){return options(formalClasses().map(c=>c.name))}function badge(v){return '<span class="pill '+(['완료','출석','제출'].includes(v)?'green':['미납','결석'].includes(v)?'red':'yellow')+'">'+esc(v)+'</span>'}function table(headers,rows){const plain=v=>String(v??'').replace(/<[^>]*>/g,'').trim();const dateFirst=/날짜|일시|청구월|제출일/.test(String(headers[0]));const nameFirst=/학생|학원/.test(String(headers[0]));if(dateFirst||nameFirst)rows=[...rows].sort((a,b)=>studentNameCollator.compare(plain(a[0]),plain(b[0]))||studentNameCollator.compare(plain(a[1]),plain(b[1])));return '<div class="tablewrap"><table><thead><tr>'+headers.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+ (rows.length?rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join(''):'<tr><td class="empty" colspan="'+headers.length+'">등록된 내용이 없습니다.</td></tr>')+'</tbody></table></div>'}async function del(type,id){if(type==='classes'){await deleteFormalClass(id);return}if(type==='students'){showStudentArchive(id);return}if(!confirm('이 기록을 삭제할까요?'))return;if(type==='tasks'&&db.tasks.find(t=>t.id===id)?.sessionEnd){try{await bookingApi('homework',{action:'archive',id})}catch(e){toast(e.message);return}}if(type==='classes'&&remote.connected){try{await bookingApi('review-videos',{action:'class-unassign',classId:id})}catch(e){toast(e.message);return}}db[type]=db[type].filter(x=>x.id!==id);save();render();toast('삭제했습니다')}async function deleteFormalClass(id){const c=formalClasses().find(c=>c.id===id);if(!c)return toast('수업을 찾지 못했습니다.');const students=db.students.filter(s=>s.class===c.name);if(!confirm('「'+c.name+'」 수업을 삭제할까요?\n배정 학생 '+students.length+'명은 수업 배정만 해제됩니다. 학생과 기존 과제·성적·출결 기록은 보존됩니다.'))return;try{if(remote.connected)await bookingApi('review-videos',{action:'class-unassign',classId:id});snapshotAttendanceAssignments();snapshotTaskRosters();for(const s of students)s.class='';db.classes=db.classes.filter(x=>x.id!==id);save();render();toast('수업 삭제와 학생 배정 해제를 완료했습니다.')}catch(e){toast(e.message||'수업을 삭제하지 못했습니다.')}}
function removeBtn(type,id){return '<button class="btn light small" data-click="del(\''+type+'\',\''+id+'\')">'+(type==='classes'?'수업 삭제':'삭제')+'</button>'}
function renderNavigation(active){
 const paths={videos:'M4 5h16v14H4z M10 9l5 3-5 3z',dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',students:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',classes:'M4 4h16v16H4z M4 10h16 M10 4v16',attendance:'M9 11l3 3L22 4 M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',tasks:'M9 5h12 M9 12h12 M9 19h12 M3 5h.01 M3 12h.01 M3 19h.01',scores:'M4 19h16 M6 15V9 M12 15V4 M18 15v-7',exams:'M8 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2h-3 M8 2h8v4H8z M8 11h8 M8 16h5',notes:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5z',reservations:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2 M8 14h3 M8 18h6',bookings:'M12 8v4l3 3 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',payments:'M3 5h18v14H3z M3 10h18 M7 15h3',notices:'M3 11v3l4 1 12 5V4L7 9l-4 2 M7 15l2 6h4',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6'};
 let html='<div class="desktop-navigation">';for(const [key,icon,label] of menus){if(key==='students')html+='<div class="nav-group-label">학습 관리</div>';if(key==='reservations')html+='<div class="nav-group-label">운영 관리</div>';if(key==='settings')html+='<div class="nav-group-label">설정</div>';html+='<button class="'+(active===key?'active':'')+'" '+(active===key?'aria-current="page"':'')+' data-click="go(\''+key+'\')"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="'+paths[key]+'"/></svg><span>'+label+'</span></button>'}html+='</div><div class="mobile-navigation"><label class="sr-only" for="mobile-menu">메뉴 이동</label><select id="mobile-menu" data-change="go(this.value)">'+menus.map(([key,icon,label])=>'<option value="'+key+'" '+(active===key?'selected':'')+'>'+label+'</option>').join('')+'</select></div>';$('#nav').innerHTML=html;
}

function render(){if(page==='weekly'){renderWeeklyReports();return}if(page==='reservations'||page==='exams'||page==='videos'){renderIntegrationPage();return}if(page==='report'){renderReport();return}let m=menus.find(m=>m[0]===page);$('#breadcrumb').textContent=m[2];renderNavigation(page==='report'?'students':page);const labels={students:'학생 등록',classes:'수업 등록',tasks:'과제 등록',scores:'성적 입력',bookings:'예약 추가',notes:'상담 기록',notices:'공지 작성'};$('#app').innerHTML='<div class="row"><div><div class="eyebrow">YE SCI · CLASS MANAGER</div><h1>'+ (page==='dashboard'?'대시보드':m[2])+'</h1><p style="margin:7px 0">'+(page==='dashboard'?'학생 현황과 오늘 확인할 업무를 한눈에 살펴보세요.': '수업의 흐름을 한눈에 확인하고 차근차근 관리하세요.')+'</p></div>'+(labels[page]?'<button class="btn" data-click="openEditor(\''+page+'\')">＋ '+labels[page]+'</button>':'<span class="pill">'+today().replaceAll('-','. ')+'</span>')+'</div><div id="view"></div><footer>YENSENSE · CLASS MANAGEMENT &nbsp; 기록은 현재 계정의 클라우드에 저장됩니다.</footer>';draw()}
function draw(){const view=$('#view');if(page==='attendance'){renderAttendancePage(view);return}if(page==='payments'){renderSettlements(view);return}if(page==='dashboard'){const a=db.attendance[today()]||{},present=attendanceStudents(today(),'','').filter(s=>['출석','지각'].includes(attendanceStatus(a[s.id]))).length,unpaid=db.payments.filter(x=>x.status==='미납');view.innerHTML='<div class="dashboard-shortcuts"><span>빠른 업무</span><div><button class="btn light small" data-click="openEditor(\'students\')">＋ 학생 등록</button><button class="btn light small" data-click="go(\'attendance\')">출결 확인</button><button class="btn light small" data-click="openEditor(\'tasks\')">＋ 과제 등록</button><button class="btn light small" data-click="openQuickExamRegistration()">＋ 시험지 등록</button></div></div><div class="stats dashboard-stats">'+[['전체 학생',currentStudents().length,'명','등록된 재원생'],['오늘 출석',present,'명','오늘 수업 '+attendanceStudents(today(),'','').length+'명 중'],['진행 중 과제',db.tasks.length,'개','반별 제출 현황 확인']].map(x=>'<div class="card"><div class="stat-label">'+x[0]+'</div><div class="stat-num">'+x[1]+'<small>'+x[2]+'</small></div><div class="tiny">'+x[3]+'</div></div>').join('')+'</div>'+dashboardTimetable()+'<div class="grid"><div class="card"><div class="row"><h3>주간 수업 일정</h3><button class="btn light small" data-click="go(\'classes\')">전체 보기 ↗</button></div>'+formalClasses().sort(compareSchedules).map((c,i)=>'<div class="classrow"><div class="time">'+esc(c.time)+'<div class="tiny" style="margin-top:6px">'+esc(c.day)+'요일</div></div><div class="colorbar" style="background:'+['#a8d2e9','#e9d88c','#b6d7c6'][i%3]+'"></div><div class="classbody"><strong>'+esc(c.name)+'</strong><small>'+esc(c.room)+' · '+esc(c.time)+'–'+esc(c.end)+'</small></div><span class="pill">'+sortedStudents(currentStudents()).filter(s=>s.class===c.name).length+' / '+esc(c.capacity)+'명</span></div>').join('')+'</div><div class="card"><h3>지금 확인할 일 <span class="pill yellow">TO DO</span></h3><div class="taskline"><span class="dot"></span><div style="flex:1">출결을 확인해 주세요<p class="tiny" style="margin:5px 0">오늘 출결 미기록 '+attendanceStudents(today(),'','').filter(s=>!a[s.id]||a[s.id]==='미기록').length+'명</p></div><button class="btn light small" data-click="go(\'attendance\')">확인</button></div>'+db.tasks.slice().sort((a,b)=>a.date.localeCompare(b.date)||studentNameCollator.compare(a.title,b.title)).slice(0,2).map(t=>'<div class="taskline"><span class="dot" style="background:#95c4da"></span><div style="flex:1">'+esc(t.title)+'<p class="tiny" style="margin:5px 0">'+esc(t.class)+' · '+t.done.length+'명 제출</p></div><button class="btn light small" data-click="go(\'tasks\')">확인</button></div>').join('')+'<div class="note">다가오는 클리닉 예약 <b>'+db.bookings.filter(b=>b.date>=today()&&b.status==='예약').length+'건</b><br>학생별 상담 기록과 학습 피드백을 함께 남겨 보세요.</div></div></div><div class="card bottom"><div class="row"><h3>최근 상담 · 피드백</h3><button class="btn light small" data-click="go(\'notes\')">기록 보기 ↗</button></div>'+db.notes.slice().sort((a,b)=>a.date.localeCompare(b.date)||studentNameCollator.compare(student(a.student),student(b.student))).slice(-2).map(n=>'<div class="classrow"><span class="avatar">'+esc(student(n.student).slice(0,1))+'</span><div class="classbody"><strong>'+esc(student(n.student))+' <span class="pill">'+esc(n.type)+'</span></strong><small>'+esc(n.memo)+'</small></div><small class="tiny">'+esc(n.date)+'</small></div>').join('')+'</div>';return}if(page==='settings'){view.innerHTML='<div class="card bottom"><h3>데이터 관리</h3><p>현재 계정의 클라우드에 자동 저장됩니다.</p><div class="toolbar"><a class="btn light" href="/cloud">계정 · 자료실</a><a class="btn light" href="/signout-with-chatgpt?return_to=%2F" target="_top">로그아웃</a><button class="btn" data-click="backup()">JSON 백업 다운로드</button><button class="btn light" data-click="document.getElementById(\'restore\').click()">백업 복원</button><input hidden id="restore" type="file" accept="application/json" data-change="restore(this)"></div><div class="note">접근: 소유자 전용 · 브라우저 로컬 저장<br>백업 파일에는 학생 정보가 포함됩니다. 안전한 개인 저장 공간에 보관하세요.<br>현재 버전: 관리자용 기본 기능<br>결제 처리는 연결되지 않았습니다. 학생 정보는 예약 서버와 통합 저장됩니다. 월별 정산은 출석 기록과 티켓 단가·비율을 기준으로 계산합니다.</div></div>';return}let tools='<div class="toolbar"><input aria-label="검색" placeholder="이름, 학교, 학원 또는 내용 검색" value="'+esc(query)+'" data-input="query=this.value;drawRows()">';if(page==='students'||page==='attendance')tools+='<select aria-label="반 필터" data-change="filter=this.value;drawRows()"><option value="">전체 수업</option>'+classOptions()+'</select>';if(page==='attendance')tools+='<input aria-label="출결 날짜" type="date" value="'+attDate+'" data-change="attDate=this.value;drawRows()"><button class="btn light" data-click="allPresent()">조회 학생 전체 출석</button>';tools+='</div>';if(page==='classes'&&typeof classReportTabs==='function')tools=classReportTabs('classes')+tools;view.innerHTML=(page==='students'?'':tools)+'<div id="rows"></div>';drawRows()}
let studentSelection=new Set(),studentDirectoryView='active',studentStatusFilter='',studentGroupMode='',studentGroupFilter='',studentBulkPending=null,studentBulkBusy=false,studentBulkMessage='';
function formalClasses(){return db.classes.filter(c=>c.kind!=='scheduling'&&!c.inactive).sort((a,b)=>studentNameCollator.compare(a.name,b.name))}
function operationalStudent(s){return !!s&&!s.archived&&s.enrollmentStatus!=='withdrawn'}
function directoryMember(s){return studentDirectoryView==='archived'?!!s.archived:!s.archived&&(studentDirectoryView==='withdrawn'?s.enrollmentStatus==='withdrawn':s.enrollmentStatus!=='withdrawn')}
function currentStudents(){return db.students.filter(operationalStudent)}
function directoryStudents(){return sortedStudents(db.students.filter(s=>directoryMember(s))).filter(s=>matched(s)&&(!studentStatusFilter||(s.enrollmentStatus||'enrolled')===studentStatusFilter)&&(!studentGroupFilter||(s.group||'')===studentGroupFilter))}
function selectedDirectoryStudents(){return db.students.filter(s=>studentSelection.has(s.id)&&directoryMember(s))}
function toggleStudentSelection(id,checked){if(studentBulkBusy||!directoryStudents().some(s=>s.id===id))return;checked?studentSelection.add(id):studentSelection.delete(id);drawRows()}
function selectAllStudents(checked){if(studentBulkBusy)return;for(const s of directoryStudents())checked?studentSelection.add(s.id):studentSelection.delete(s.id);drawRows()}
function clearStudentSelection(){if(studentBulkBusy)return;studentSelection.clear();drawRows()}
function setStudentDirectoryView(value){if(studentBulkBusy||!['active','withdrawn','archived'].includes(value))return;studentDirectoryView=value;studentStatusFilter='';studentSelection.clear();studentBulkMessage='';drawRows()}
function setStudentGrouping(value){if(studentBulkBusy)return;if(!['','group','class','school','academy'].includes(value))return;studentGroupMode=value;drawRows()}
function setStudentGroupFilter(value){if(studentBulkBusy)return;studentGroupFilter=value;drawRows()}
function applyStudentBulkGroup(){if(studentBulkBusy)return;const students=selectedDirectoryStudents();if(!students.length||studentDirectoryView==='archived')return toast('재원 학생을 선택해 주세요.');const group=String($('#student-bulk-group').value||'').trim();if(group.length>80||/[\u0000-\u001f\u007f]/.test(group))return toast('그룹명은 80자 이내로 입력해 주세요.');for(const s of students)s.group=group;save();studentBulkMessage=students.length+'명의 그룹을 '+(group?'「'+group+'」으로 변경했습니다.':'해제했습니다.');drawRows()}
function snapshotTaskRosters(){for(const t of db.tasks)if(!Array.isArray(t.studentIds))t.studentIds=[...new Set([...db.students.filter(s=>s.class===t.class).map(s=>s.id),...(t.done||[])])]}
function assignClassStudents(students,className){snapshotAttendanceAssignments();snapshotTaskRosters();for(const s of students){if(!operationalStudent(s))continue;s.class=className;for(const t of db.tasks.filter(t=>className&&t.class===className)){t.studentIds??=[];if(!t.studentIds.includes(s.id))t.studentIds.push(s.id)}}}
function applyStudentBulkClass(){if(studentBulkBusy)return;const c=formalClasses().find(c=>c.id===$('#student-bulk-class').value),students=selectedDirectoryStudents();if(!c||!students.length||studentDirectoryView==='archived')return toast('학생과 배정할 수업을 선택해 주세요.');assignClassStudents(students,c.name);save();studentBulkMessage=students.length+'명을 「'+c.name+'」 수업으로 배정했습니다. 개인·주간 리포트에도 반영됩니다.';drawRows()}
function clearStudentBulkClass(){if(studentBulkBusy||studentDirectoryView==='archived')return;const students=selectedDirectoryStudents().filter(s=>s.class);if(!students.length)return toast('배정된 학생을 선택해 주세요.');assignClassStudents(students,'');save();studentBulkMessage=students.length+'명의 수업 배정을 취소했습니다. 기존 과제·성적·예약 기록은 유지됩니다.';drawRows()}
function classRosterPicker(className){return '<fieldset class="class-roster"><legend>수강생 일괄 배정</legend><p class="muted">체크한 학생을 이 수업에 배정합니다. 다른 수업에 배정된 학생은 이 수업으로 이동합니다. 체크를 해제한 기존 수강생은 미배정으로 변경됩니다.</p><input type="search" aria-label="수강생 검색" placeholder="이름·학교·그룹 검색" data-input="filterClassRoster(this.value)"><div class="class-roster-tools"><label><input type="checkbox" id="roster-all" data-change="toggleClassRosterAll(this.checked)"> 조회 학생 전체 선택</label></div><div class="class-roster-list">'+sortedStudents(currentStudents()).map(s=>'<label class="class-roster-row" data-search="'+esc([s.name,s.school,s.group||''].join(' '))+'"><input type="checkbox" name="classStudent" data-change="syncClassRosterAll()" value="'+esc(s.id)+'" '+(className&&s.class===className?'checked':'')+'><span><b>'+esc(s.name)+'</b><small>'+esc([s.school,s.class||'미배정'].filter(Boolean).join(' · '))+'</small></span></label>').join('')+(!currentStudents().length?'<p>등록된 학생이 없습니다. 학생 등록 후 수업 수정에서 배정할 수 있습니다.</p>':'')+'</div></fieldset>'}
function selectClassRoster(mode){const checked=mode==='all';document.querySelectorAll('.class-roster-row').forEach(row=>{if(!row.hidden)row.querySelector('input').checked=checked});syncClassRosterAll()}
function filterClassRoster(value){const q=value.trim().toLocaleLowerCase('ko');document.querySelectorAll('.class-roster-row').forEach(row=>{row.hidden=!row.dataset.search.toLocaleLowerCase('ko').includes(q)});syncClassRosterAll()}

function showStudentArchive(id){if(studentBulkBusy)return;const students=id?db.students.filter(s=>s.id===id):selectedDirectoryStudents();if(!students.length)return toast('학생을 선택해 주세요.');const restore=students.every(s=>s.archived);if(students.some(s=>!!s.archived!==restore))return toast('삭제 또는 복원할 명단을 다시 확인해 주세요.');studentBulkPending={ids:students.map(s=>s.id),restore};$('#modal').innerHTML='<h2>학생 '+students.length+'명 '+(restore?'복원':'삭제')+'</h2><p>'+(restore?'학생 목록에 복원하고 연결된 예약 계정의 예약을 다시 허용합니다.':'학생 목록에서 제외하고 연결된 예약 계정의 예약을 중지합니다. 출결·과제·성적·예약 기록은 보존되며 삭제된 학생 목록에서 복원할 수 있습니다.')+'</p><div class="student-bulk-names">'+sortedStudents(students).map(s=>'<div><b>'+esc(s.name)+'</b> · '+esc(s.school)+' · '+esc(s.class)+'</div>').join('')+'</div><div class="actions"><button class="btn light" data-click="document.getElementById(\'modal\').close()">취소</button><button class="btn" data-click="confirmStudentArchive()">'+(restore?'선택 학생 복원':'선택 학생 삭제')+'</button></div>';$('#modal').showModal()}
async function confirmStudentArchive(){if(studentBulkBusy||!studentBulkPending)return;const pending=studentBulkPending;studentBulkPending=null;studentBulkBusy=true;$('#modal').close();studentBulkMessage='선택한 학생을 처리하고 있습니다…';if(page==='students')drawRows();const failed=[];let done=0;try{for(const id of pending.ids){const s=db.students.find(s=>s.id===id);if(!s||!!s.archived!==pending.restore)continue;try{if(remote.connected&&s.bookingStudentId)await persistUnifiedStudent({...s,active:pending.restore},s);s.archived=!pending.restore;save();studentSelection.delete(id);done++}catch(e){failed.push(s.name+': '+e.message)}}studentBulkMessage=done+'명 '+(pending.restore?'복원':'삭제')+' 완료'+(failed.length?' · '+failed.length+'명 처리 실패 — '+failed.join(' / '):'');}finally{studentBulkBusy=false;if(page==='students')drawRows();else render();toast(done+'명 '+(pending.restore?'복원':'삭제')+' 처리했습니다.')}}
function studentDirectoryTable(students){return table(['<input class="student-select" type="checkbox" aria-label="조회 학생 전체 선택" data-change="selectAllStudents(this.checked)" '+(students.length&&students.every(s=>studentSelection.has(s.id))?'checked':'')+'>','학생','학교 · 학년','소속 학원','그룹','정식 강좌','학생 연락처','학부모 연락처','관리'],students.map(s=>['<input class="student-select" type="checkbox" aria-label="'+esc(s.name+' · '+s.school+' 선택')+'" '+(studentSelection.has(s.id)?'checked':'')+' '+(studentBulkBusy?' disabled':'')+' data-change="toggleStudentSelection(\''+esc(s.id)+'\',this.checked)">',studentLink(s),esc(s.school+' · '+s.grade),esc(s.academy||'미입력'),'<span class="pill">'+esc(s.group||'미지정')+'</span>','<span class="pill">'+esc(s.class||'미배정')+'</span>',esc(s.phone),esc(s.parentPhone||'미입력'),s.archived?'<button class="btn light small" data-click="showStudentArchive(\''+esc(s.id)+'\')">복원</button>':'<button class="btn light small" data-click="showStudentCredentials(\''+esc(s.id)+'\')">닉네임·PIN</button> <button class="btn light small" data-click="openEditor(\'students\',\''+esc(s.id)+'\')">수정</button> '+removeBtn('students',s.id)]))}
function renderStudentDirectory(){if(studentGroupFilter&&!db.students.some(s=>directoryMember(s)&&(s.group||'')===studentGroupFilter))studentGroupFilter='';const students=directoryStudents(),selected=selectedDirectoryStudents(),groups=[...new Set(db.students.filter(s=>directoryMember(s)).map(s=>s.group||'').filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ko')),all=students.length>0&&students.every(s=>studentSelection.has(s.id)),visibleSelected=students.filter(s=>studentSelection.has(s.id)).length,disabled=studentBulkBusy?' disabled':'';let html='<div class="student-directory-tools"><div class="student-directory-tabs"><button class="btn '+(studentDirectoryView==='active'?'':'light')+'" data-click="setStudentDirectoryView(\'active\')"'+disabled+'>학생 목록 '+currentStudents().length+'</button><button class="btn '+(studentDirectoryView==='withdrawn'?'':'light')+'" data-click="setStudentDirectoryView(\'withdrawn\')"'+disabled+'>퇴원생 '+db.students.filter(s=>!s.archived&&s.enrollmentStatus==='withdrawn').length+'</button><button class="btn '+(studentDirectoryView==='archived'?'':'light')+'" data-click="setStudentDirectoryView(\'archived\')"'+disabled+'>삭제된 학생 '+db.students.filter(s=>s.archived).length+'</button></div><div class="student-directory-filters"><label class="student-search-field">학생 검색<input aria-label="검색" placeholder="이름 · 학교 · 학원 검색" value="'+esc(query)+'" data-input="query=this.value;drawRows()"></label><label>수업<select aria-label="반 필터" data-change="filter=this.value;drawRows()"><option value="">전체 수업</option>'+options(formalClasses().map(c=>c.name),filter)+'</select></label><label>그룹 필터<select data-change="setStudentGroupFilter(this.value)"'+disabled+'><option value="">전체 그룹</option>'+groups.map(g=>'<option '+(g===studentGroupFilter?'selected':'')+'>'+esc(g)+'</option>').join('')+'</select></label><label>재원 상태<select aria-label="재원 상태 필터" data-change="studentStatusFilter=this.value;studentSelection.clear();drawRows()"><option value="">전체 상태</option>'+[['enrolled','재원생'],['withdrawn','퇴원생'],['prospective','예비원생']].map(([v,n])=>'<option value="'+v+'" '+(studentStatusFilter===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>모아 보기<select data-change="setStudentGrouping(this.value)">'+[['','전체 목록'],['group','그룹별'],['class','수업별'],['school','학교별'],['academy','학원별']].map(([key,label])=>'<option value="'+key+'" '+(studentGroupMode===key?'selected':'')+'>'+label+'</option>').join('')+'</select></label></div></div><section class="student-bulk-toolbar" '+(!selected.length?'hidden':'')+'><div class="student-selection-line"><b>'+selected.length+'명 선택</b>'+(selected.length-visibleSelected>0?'<small>현재 검색 밖 '+(selected.length-visibleSelected)+'명 포함</small>':'')+'</div>' +(studentDirectoryView==='active'?'<div class="student-bulk-actions"><label>그룹명<input id="student-bulk-group" maxlength="80" placeholder="예: 중3 내신 · 빈칸 적용 시 해제"'+disabled+'></label><button class="btn light" data-click="applyStudentBulkGroup()"'+(!selected.length?' disabled':'')+disabled+'>그룹 적용</button><label>배정할 수업<select id="student-bulk-class"'+disabled+'><option value="">수업 선택</option>'+formalClasses().map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('')+'</select></label><button class="btn light" data-click="applyStudentBulkClass()"'+(!selected.length?' disabled':'')+disabled+'>수업 배정</button><button class="btn light" data-click="clearStudentBulkClass()"'+(!selected.length?' disabled':'')+disabled+'>배정 취소</button><button class="btn student-delete" data-click="showStudentArchive()"'+(!selected.length?' disabled':'')+disabled+'>선택 삭제</button></div>':studentDirectoryView==='archived'?'<div class="actions"><button class="btn" data-click="showStudentArchive()"'+(!selected.length?' disabled':'')+disabled+'>선택 학생 복원</button></div>':'<div class="note">퇴원생의 PIN과 영상 접근은 중지되어 있습니다. 학생 수정에서 재원 상태를 변경할 수 있습니다.</div>')+'</section>'+(studentBulkMessage?'<div class="note" role="status">'+esc(studentBulkMessage)+'</div>':'');if(!studentGroupMode)return html+studentDirectoryTable(students);const buckets=new Map();for(const s of students){const key=s[studentGroupMode]||'미지정';if(!buckets.has(key))buckets.set(key,[]);buckets.get(key).push(s)}return html+([...buckets].sort(([a],[b])=>a.localeCompare(b,'ko')).map(([key,rows])=>'<section class="student-group-section"><h3>'+esc(key)+' <span class="pill">'+rows.length+'명</span></h3>'+studentDirectoryTable(rows)+'</section>').join('')||'<div class="report-empty">조건에 맞는 학생이 없습니다.</div>')}

function attendanceStatus(value){return value==='하원'?'출석':value}function matched(s){return (!filter||s.class===filter)&&[s.name,s.school,s.academy||'',s.class,s.grade,s.group||''].some(v=>v.includes(query))}function drawRows(){let r=[];if(page==='students')r=renderStudentDirectory();if(page==='classes')r=renderClassDirectory();if(page==='attendance')r=attendanceRoster();if(page==='tasks')r=db.tasks.filter(t=>JSON.stringify(t).includes(query)).sort((a,b)=>a.date.localeCompare(b.date)||studentNameCollator.compare(a.title,b.title)).map(t=>{const students=sortedStudents(currentStudents()).filter(s=>taskAssigned(t,s));return '<div class="card bottom"><div class="row"><h3>'+esc(t.title)+'</h3><div class="actions"><button class="btn light small" data-click="openEditor(\'tasks\',\''+t.id+'\')">수업일 설정 · 수정</button>'+removeBtn(page,t.id)+'</div>'+'</div><p>'+esc(t.class)+' · 마감 '+esc(t.date)+(t.sessionEnd?' · 자동 분류 <button class="btn light small" data-click="refreshHomework()">최신 제출 확인</button>':'')+' · 제출 '+students.filter(s=>taskSubmitted(t,s.id)).length+'/'+students.length+'명</p>'+taskStatusSummary(students.map(s=>taskStatus(t,s.id)))+ (students.length?'<div class="task-students">'+students.map(s=>'<div class="task-student">'+taskStatusControl(t,s.id,true)+studentLink(s,false)+(t.sessionEnd?'<button class="btn light small" data-click="showHomeworkFiles(\''+t.id+'\',\''+s.id+'\')">제출물</button>':'')+'</div>').join('')+'</div>':'<p>이 반에 등록된 학생이 없습니다.</p>')+'</div>'}).join('')||'<div class="empty">등록된 과제가 없습니다.</div>';if(page==='scores')r=table(['학생','평가명','점수','평가일','관리'],db.scores.filter(x=>operationalStudent(db.students.find(s=>s.id===x.student))&&(student(x.student)+x.title).includes(query)).sort((a,b)=>compareStudentNames(db.students.find(s=>s.id===a.student)||{name:student(a.student)},db.students.find(s=>s.id===b.student)||{name:student(b.student)})).map(x=>[esc(student(x.student)),esc(x.title),'<span class="gradebar"><i style="width:'+Number(x.score)+'%"></i></span><b>'+esc(x.score)+'</b> / 100',esc(x.date),removeBtn(page,x.id)]));if(page==='bookings')r=table(['학생','일시','내용','예약 상태','관리'],db.bookings.filter(x=>operationalStudent(db.students.find(s=>s.id===x.student))&&(student(x.student)+x.memo).includes(query)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).sort((a,b)=>compareStudentNames(db.students.find(s=>s.id===a.student)||{name:student(a.student)},db.students.find(s=>s.id===b.student)||{name:student(b.student)})).map(x=>[esc(student(x.student)),esc(x.date+' '+x.time),esc(x.memo),'<select aria-label="예약 상태" data-change="changeStatus(\'bookings\',\''+x.id+'\',this.value)">'+options(['예약','완료','취소'],x.status)+'</select>',removeBtn(page,x.id)]));if(page==='notes')r=table(['학생','날짜','유형','상담 내용','관리'],db.notes.filter(x=>operationalStudent(db.students.find(s=>s.id===x.student))&&(student(x.student)+x.memo).includes(query)).slice().reverse().sort((a,b)=>compareStudentNames(db.students.find(s=>s.id===a.student)||{name:student(a.student)},db.students.find(s=>s.id===b.student)||{name:student(b.student)})).map(x=>[esc(student(x.student)),esc(x.date),badge(x.type),'<span style="display:block;white-space:pre-wrap;min-width:240px;max-width:440px;line-height:1.7">'+esc(x.memo)+'</span>',removeBtn(page,x.id)]));if(page==='payments')r='<div class="note">수납 내역을 수기로 기록하는 화면입니다. 실제 결제는 발생하지 않습니다.</div>'+table(['학생','청구월','금액','수납 상태','관리'],db.payments.filter(x=>student(x.student).includes(query)).sort((a,b)=>compareStudentNames(db.students.find(s=>s.id===a.student)||{name:student(a.student)},db.students.find(s=>s.id===b.student)||{name:student(b.student)})).map(x=>[esc(student(x.student)),esc(x.month),Number(x.amount).toLocaleString()+'원','<select aria-label="수납 상태" data-change="changeStatus(\'payments\',\''+x.id+'\',this.value)">'+options(['미납','완료'],x.status)+'</select>',removeBtn(page,x.id)]));if(page==='notices')r=db.notices.filter(x=>(x.title+x.body).includes(query)).sort((a,b)=>a.date.localeCompare(b.date)||studentNameCollator.compare(a.title,b.title)).map(x=>'<div class="card bottom"><div class="row"><h3>'+esc(x.title)+'</h3>'+removeBtn(page,x.id)+'</div><span class="tiny">'+esc(x.date)+'</span><p style="white-space:pre-wrap;color:#526b75">'+esc(x.body)+'</p></div>').join('')||'<div class="empty">공지사항이 없습니다.</div>';$('#rows').innerHTML=r;if(page==='students'){const box=$('#student-select-all');if(box){const rows=directoryStudents(),n=rows.filter(s=>studentSelection.has(s.id)).length;box.indeterminate=n>0&&n<rows.length}}}function setAtt(id,v){if(page==='attendance'&&!attendanceStudents().some(s=>s.id===id))return toast('선택한 날짜·수업의 학생만 출결을 변경할 수 있습니다.');captureAttendanceAssignment(attDate,id);db.attendance[attDate]??={};db.attendance[attDate][id]=v;save();toast('출결을 저장했습니다')}function allPresent(){const students=attendanceStudents();if(!students.length)return toast('이 날짜·수업에 출석 처리할 학생이 없습니다.');db.attendance[attDate]??={};students.forEach(s=>{captureAttendanceAssignment(attDate,s.id);db.attendance[attDate][s.id]='출석'});save();drawRows();toast('조회된 학생을 출석 처리했습니다')}function taskDone(id,s,checked){setTaskStatus(id,s,checked?'ontime':'missing')}function changeStatus(type,id,v){db[type].find(x=>x.id===id).status=v;save();toast('상태를 저장했습니다')}
function field(label,name,type='text',value='',extra=''){return '<label>'+label+'<input required name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>'}function select(label,name,opts){return '<label>'+label+'<select required name="'+name+'">'+opts+'</select></label>'}function openEditor(type,id){if(['scores','bookings','notes','payments'].includes(type)&&!currentStudents().length){toast('학생을 먼저 등록해 주세요');return}if(type==='tasks'&&!formalClasses().length){toast('수업을 먼저 등록해 주세요');return}let x=id?db[type].find(x=>x.id===id):{},f='';if(type==='students')f=field('학생 이름','name','text',x.name||'')+select('재원 상태','enrollmentStatus',[['enrolled','재원생'],['withdrawn','퇴원생'],['prospective','예비원생']].map(([v,n])=>'<option value="'+v+'" '+((x.enrollmentStatus||'enrolled')===v?'selected':'')+'>'+n+'</option>').join(''))+field('예약 닉네임','nickname','text',x.nickname||remote.students.find(s=>s.id===x.bookingStudentId)?.nickname||'','minlength="2" maxlength="24" autocomplete="off" spellcheck="false"')+'<p class="student-account-help">한글·영문·숫자·_·- 2~24자. 영문은 소문자로 저장됩니다.</p>'+field('학교','school','text',x.school||'')+'<label>소속 학원 (선택)<input name="academy" maxlength="80" value="'+esc(x.academy||'')+'" placeholder="예: ○○과학학원"></label><label>그룹 (선택)<input name="group" maxlength="80" value="'+esc(x.group||'')+'" placeholder="예: 중3 내신"></label>'+select('학년','grade',options(['중1','중2','중3','고1','고2','고3'],x.grade))+'<label>정식 수강 강좌 (선택)<select name="class"><option value="">미배정</option>'+options(formalClasses().map(c=>c.name),x.class)+'</select></label>'+field('학생 연락처','phone','tel',x.phone||'')+'<label>학부모 연락처 (선택)<input name="parentPhone" type="tel" value="'+esc(x.parentPhone||remote.contacts.find(c=>c.student_id===x.bookingStudentId)?.parent_phone||'')+'" placeholder="학부모 연락처 별도 입력"></label>'+(remote.connected?'<div class="student-pin-info"><b>예약 PIN '+(id?'유지':'자동 발급')+'</b><p>'+(id?'기존 PIN은 유지됩니다. 새 PIN이 필요할 때만 아래를 선택하세요.':'학생 등록 시 YE + 숫자 4자리 PIN을 자동 발급합니다. 저장 후 닉네임과 PIN을 확인할 수 있습니다.')+'</p>'+(id?'<label class="student-pin-reset"><input type="checkbox" name="resetPin">새 PIN 발급 · 기존 PIN과 저장된 접속 해제</label>':'')+'</div>':'');if(type==='classes')f=field('수업명','name','text',x.name||'')+classAcademyField(x)+select('수업 요일','day',options(['월','화','수','목','금','토','일'],x.day))+field('시작 시간','time','time',x.time||'16:00')+field('종료 시간','end','time',x.end||'18:30')+field('정원','capacity','number',x.capacity||12,'min="1" max="999"')+field('강의실','room','text',x.room||'A 강의실')+classRosterPicker(x.name||'');if(type==='tasks')f=field('과제명','title','text',x.title||'')+select('수강 수업','class',options(formalClasses().map(c=>c.name),x.class))+field('과제를 낸 수업일','sessionDate','date',x.sessionDate||today())+field('다음 수업 시작 (휴강·보강 시 수정)','nextStart','datetime-local',x.nextStart?homeworkLocalTime(x.nextStart):'')+'<p class="student-account-help">수업 종료 시각은 수업 관리의 종료 시간을 사용합니다. 정시 마감은 종료 후 72시간입니다. 다음 수업은 기본 7일 후이며, 직접 변경할 수 있습니다. 연결된 학생 계정에만 공개됩니다.</p>';if(type==='scores')f=select('학생','student',so())+field('평가명','title')+field('점수 (100점 만점)','score','number','','min="0" max="100" step="0.1"')+field('평가일','date','date',today());if(type==='bookings')f=select('학생','student',so())+field('예약 날짜','date','date',today())+field('시작 시간 · 1시간 클리닉','time','time','18:30','step="1800"')+field('피드백 내용','memo');if(type==='notes')f=select('학생','student',so())+field('상담일','date','date',today())+select('상담 유형','type',options(['학습 상담','학부모 상담','진로 상담','기타']))+'<label>상담 내용<textarea required name="memo" rows="5"></textarea></label>';if(type==='payments')f=select('학생','student',so())+field('청구월','month','month',today().slice(0,7))+field('금액 (원)','amount','number','','min="0" step="1"')+select('수납 상태','status',options(['미납','완료']));if(type==='notices')f=field('공지 제목','title')+'<label>공지 내용<textarea name="body" required rows="6"></textarea></label>';$('#modal').innerHTML='<h2>'+({students:'학생',classes:'수업',tasks:'과제',scores:'성적',bookings:'클리닉 예약',notes:'상담',payments:'수납',notices:'공지'}[type])+' '+(id?'수정':'등록')+'</h2><form id="editor"><div class="fields">'+f+'</div><div class="actions"><button type="button" class="btn light" data-click="document.getElementById(\'modal\').close()">취소</button><button class="btn" type="submit">저장하기</button></div></form>';if(type==='classes')syncClassRosterAll();if(type==='tasks')setupHomeworkEditor();$('#editor').onsubmit=async e=>{e.preventDefault();const formData=new FormData(e.target),rosterIds=type==='classes'?new Set(formData.getAll('classStudent')):null;let v=Object.fromEntries(formData);delete v.classStudent;if(type==='students'){snapshotAttendanceAssignments();v.academy=String(v.academy||'').trim();v.group=String(v.group||'').trim();v.parentPhone=String(v.parentPhone||'').replace(/\D/g,'');if(v.parentPhone&&!/^0\d{9,10}$/.test(v.parentPhone))return toast('학부모 연락처를 확인해 주세요.');v.nickname=String(v.nickname||'').normalize('NFKC').trim().toLowerCase();if(!/^[가-힣a-z0-9_-]{2,24}$/.test(v.nickname))return toast('닉네임은 한글·영문·숫자·_·- 2~24자로 입력해 주세요.');}if(Object.entries(v).some(([key,value])=>!['academy','group','parentPhone',...(type==='students'?['class']:[])].includes(key)&&!value.trim()))return toast('빈칸을 입력해 주세요');if(type==='classes'){snapshotAttendanceAssignments();v.academy=String(v.academy||'').trim();if(v.academy.length>80||/[\u0000-\u001f\u007f]/.test(v.academy))return toast('학원명은 80자 이내로 입력해 주세요.');v.kind='formal';if(v.time>=v.end)return toast('종료 시간은 시작 시간보다 늦어야 합니다');if(formalClasses().some(c=>c.name===v.name&&c.id!==id))return toast('같은 이름의 수업이 있습니다');snapshotTaskRosters();const removed=currentStudents().filter(s=>s.class===x.name&&!rosterIds.has(s.id));assignClassStudents(removed,'');assignClassStudents(currentStudents().filter(s=>rosterIds.has(s.id)),v.name);if(id&&x.name!==v.name){db.students.forEach(s=>{if(s.class===x.name)s.class=v.name});db.tasks.forEach(t=>{if(t.class===x.name)t.class=v.name})}}if(type==='bookings'){v.status='예약';const minutes=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);if(db.bookings.some(b=>b.student===v.student&&b.date===v.date&&b.status==='예약'&&Math.abs(minutes(b.time)-minutes(v.time))<60))return toast('이 학생의 다른 예약과 시간이 겹칩니다')}if(type==='tasks'){const c=formalClasses().find(c=>c.name===v.class);v.sessionEnd=new Date(v.sessionDate+'T'+c.end+':00+09:00').toISOString();v.nextStart=new Date(v.nextStart+':00+09:00').toISOString();if(Date.parse(v.nextStart)<=Date.parse(v.sessionEnd)+72*3600000)return toast('다음 수업 시작은 수업 종료 72시간 이후로 지정해 주세요.');v.date=new Date(Date.parse(v.sessionEnd)+72*3600000).toLocaleDateString('en-CA',{timeZone:'Asia/Seoul'});v.done=x.done||[];v.studentIds=x.studentIds||sortedStudents(currentStudents()).filter(s=>s.class===v.class).map(s=>s.id);v.id=id||uid();try{if(remote.connected&&!portalWorkspaceId)await publishHomework(v)}catch(error){return toast(error.message)}}if(type==='notices')v.date=today();let issued=[];if(type==='students'&&remote.connected){if(!id)v.id=uid();const button=e.target.querySelector('button[type=submit]');if(button)button.disabled=true;try{const linked=await persistUnifiedStudent(v,id?x:null);v.bookingStudentId=linked.bookingStudentId;v.nickname=linked.nickname;delete v.resetPin;issued=linked.credentials}catch(error){if(button)button.disabled=false;toast(error.message);return}}if(type==='students')delete v.resetPin;if(type==='classes'&&id&&!x.academy&&v.academy)applyInitialClassAcademy(id,v.academy);if(id)Object.assign(x,v);else {v.id??=uid();db[type].push(v)}if(type==='students')db.tasks.filter(t=>t.class===v.class).forEach(t=>{t.studentIds??=[];if(!t.studentIds.includes(v.id||id))t.studentIds.push(v.id||id)});save();$('#modal').close();render();toast('저장했습니다');if(issued.length)showUnifiedCredentials(issued);else if(type==='students'&&!id)showStudentCredentials(v.id)};if(page==='report'&&$('#editor select[name=student]'))$('#editor select[name=student]').value=reportStudent;$('#modal').showModal()}

let reportStudent='',reportTab='overview',reportStart='',reportEnd='';
const reportTabs=[['overview','종합 리포트'],['attendance','출결'],['tasks','과제'],['scores','성적'],['notes','상담'],['bookings','예약 현황'],['connection','연동 설정']];
const taskStates={pending:{label:'제출대기',icon:'·',help:'정시 마감 전'},overdue:{label:'지각제출 대기',icon:'◷',help:'다음 수업 시작 전'},ontime:{label:'정시제출',icon:'✓',help:'마감 안에 제출한 과제'},late:{label:'지각제출',icon:'◷',help:'마감 후 제출한 과제'},missing:{label:'미제출',icon:'−',help:'아직 제출하지 않은 과제'},insufficient:{label:'미흡',icon:'!',help:'제출했지만 보완이 필요한 과제'}};
function taskStatus(t,id){const online=typeof onlineHomeworkStatus==='function'?onlineHomeworkStatus(t,id):null;if(online)return online;return Object.hasOwn(t.statuses||{},id)?t.statuses[id]:(t.done||[]).includes(id)?'ontime':'missing'}
function taskSubmitted(t,id){return ['ontime','late','insufficient'].includes(taskStatus(t,id))}
function taskStatusSummary(statuses){return '<div class="task-summary">'+Object.entries(taskStates).map(([key,state])=>'<span class="task-tag task-'+key+'">'+state.label+' '+statuses.filter(s=>s===key).length+'</span>').join('')+'</div>'}
function taskStatusIcon(key){const paths={late:'<circle cx="12" cy="12" r="8"/><path d="M12 6v6h6"/>',missing:'<path d="M6 12h12"/>'};return Object.hasOwn(paths,key)?'<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'+paths[key]+'</svg>':taskStates[key].icon}
function taskStatusControl(t,id,compact=false){const key=taskStatus(t,id),state=taskStates[key];return '<button type="button" class="task-status '+(compact?'task-status-compact ':'')+'task-'+key+'" aria-haspopup="dialog" title="'+esc(state.label+' · 눌러서 변경')+'" aria-label="'+esc(student(id)+' · '+t.title+' · '+state.label+' · 상태 변경')+'" data-click="showTaskStatus(\''+esc(t.id)+'\',\''+esc(id)+'\')"><span class="task-status-icon" aria-hidden="true">'+taskStatusIcon(key)+'</span>'+(compact?'':'<span>'+state.label+'</span><span class="task-chevron" aria-hidden="true">⌄</span>')+'</button>'}
function showTaskStatus(taskId,studentId){const t=db.tasks.find(t=>t.id===taskId),s=db.students.find(s=>s.id===studentId);if(!t||!s||!taskAssigned(t,s))return;const current=taskStatus(t,studentId);$('#modal').innerHTML='<h2 id="task-status-title" tabindex="-1">과제 제출 상태</h2><p class="task-dialog-context">'+esc(s.name)+' · '+esc(t.title)+'</p><div class="task-status-options" role="group" aria-label="제출 상태 선택">'+Object.entries(taskStates).filter(([key])=>!['pending','overdue'].includes(key)).map(([key,state])=>'<button type="button" class="task-status-option task-'+key+' '+(current===key?'selected':'')+'" aria-pressed="'+(current===key)+'" data-click="setTaskStatus(\''+esc(taskId)+'\',\''+esc(studentId)+'\',\''+key+'\')"><span class="task-status-icon" aria-hidden="true">'+taskStatusIcon(key)+'</span><span><strong>'+state.label+'</strong><small>'+state.help+'</small></span>'+(current===key?'<span class="task-selected" aria-hidden="true">✓</span>':'')+'</button>').join('')+'</div><div class="actions"><button type="button" class="btn light" data-click="document.getElementById(\'modal\').close()">취소</button></div>';$('#modal').showModal();$('#task-status-title').focus()}
function setTaskStatus(taskId,studentId,status){if(typeof remoteHomeworkReview==='function'&&db.tasks.find(t=>t.id===taskId)?.sessionEnd){remoteHomeworkReview(taskId,studentId,status);return}const t=db.tasks.find(t=>t.id===taskId),s=db.students.find(s=>s.id===studentId);if(!t||!s||!taskAssigned(t,s)||!Object.hasOwn(taskStates,status))return;t.statuses??={};t.statuses[studentId]=status;t.done=status==='missing'?(t.done||[]).filter(id=>id!==studentId):[...new Set([...(t.done||[]),studentId])];save();$('#modal').close();if(page==='report')renderReport();else drawRows();toast('과제 상태 저장: '+taskStates[status].label)}
function taskAssigned(t,s){return (t.studentIds?t.studentIds.includes(s.id):t.class===s.class)||(t.done||[]).includes(s.id)||Object.hasOwn(t.statuses||{},s.id)}
function enrollmentBadge(s){const status=s.enrollmentStatus||'enrolled',label={enrolled:'재원생',withdrawn:'퇴원생',prospective:'예비원생'}[status]||'재원생',text={enrolled:'재',withdrawn:'퇴',prospective:'예'}[status]||'재';return '<span class="enrollment-badge enrollment-'+status+'" title="'+label+'" aria-label="'+label+'">'+text+'</span>'}
function studentLink(s,showEnrollment=true){return (showEnrollment?enrollmentBadge(s):'')+'<button class="student-link" data-click="openStudentPanel(this.dataset.student)" data-student="'+esc(s.id)+'" aria-label="'+esc(s.name)+' 개인 리포트">'+esc(s.name)+'</button>'}
function showReport(id){if(!validId(id)){toast('올바르지 않은 학생 주소입니다');return}reportStudent=id;reportTab='overview';reportStart='';reportEnd='';page='report';const hash='#student/'+encodeURIComponent(id);if(location.hash!==hash)history.pushState(null,'',hash);render();window.scrollTo(0,0)}
function within(date){return (!reportStart||date>=reportStart)&&(!reportEnd||date<=reportEnd)}
function reportData(id,period){const inPeriod=period?date=>(!period.start||date>=period.start)&&(!period.end||date<=period.end):within;const s=db.students.find(s=>s.id===id);if(!s)return null;const attendance=Object.entries(db.attendance).filter(([date,entries])=>inPeriod(date)&&entries[id]&&entries[id]!=='미기록').map(([date,entries])=>({date,status:attendanceStatus(entries[id])})).sort((a,b)=>a.date.localeCompare(b.date));const tasks=db.tasks.filter(t=>taskAssigned(t,s)&&inPeriod(t.date)).slice().sort((a,b)=>a.date.localeCompare(b.date));const scores=db.scores.filter(x=>x.student===id&&inPeriod(x.date)).slice().sort((a,b)=>a.date.localeCompare(b.date));const notes=db.notes.filter(x=>x.student===id&&inPeriod(x.date)).slice().sort((a,b)=>a.date.localeCompare(b.date));const bookings=db.bookings.filter(x=>x.student===id&&inPeriod(x.date)).slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const payments=db.payments.filter(x=>x.student===id&&(!(period?period.start:reportStart)||x.month>=(period?period.start:reportStart).slice(0,7))&&(!(period?period.end:reportEnd)||x.month<=(period?period.end:reportEnd).slice(0,7)));const counted=attendance.filter(a=>a.date<=today()),present=counted.filter(a=>['출석','지각'].includes(a.status)).length,taskCounts=Object.fromEntries(Object.keys(taskStates).map(key=>[key,tasks.filter(t=>taskStatus(t,id)===key).length])),submitted=tasks.filter(t=>taskSubmitted(t,id)).length;return {taskCounts,s,attendance,tasks,scores,notes,bookings,payments,counted,present,submitted,rate:counted.length?Math.round(present/counted.length*100):null,taskRate:tasks.length?Math.round(submitted/tasks.length*100):null,average:scores.length?Math.round(scores.reduce((sum,x)=>sum+Number(x.score),0)/scores.length*10)/10:null,unpaid:payments.filter(x=>x.status==='미납').reduce((sum,x)=>sum+Number(x.amount),0)}}
function setPeriod(p){reportStart=p==='month'?today().slice(0,7)+'-01':'';reportEnd=p==='month'?today():'';renderReport()}
function setReportDate(name,value){if(name==='start')reportStart=value;else reportEnd=value;renderReport()}
function setReportTab(tab){reportTab=tab;renderReport()}
function reportEdit(type){openEditor(type)}
function reportAtt(date,status){captureAttendanceAssignment(date,reportStudent);db.attendance[date]??={};db.attendance[date][reportStudent]=status;save();renderReport();toast('출결과 리포트를 함께 업데이트했습니다')}
function reportTask(id,checked){taskDone(id,reportStudent,checked)}
function reportStatus(type,id,status){changeStatus(type,id,status);renderReport()}
function renderReport(){const d=reportData(reportStudent);$('#breadcrumb').textContent='학생 관리 / 개인 리포트';renderNavigation(page==='report'?'students':page);if(!d){$('#app').innerHTML='<h1>학생을 찾을 수 없습니다</h1><p>삭제되었거나 이 브라우저에 등록되지 않은 학생입니다.</p><button class="btn" data-click="go(\'students\')">학생 목록으로</button>';return}
const s=d.s;$('#app').innerHTML='<div class="row no-print"><button class="btn light small" data-click="go(\'students\')">← 학생 목록</button><button class="btn small" data-click="showReportComposer()">리포트 보내기</button></div><div class="card report-profile"><div class="row"><div style="display:flex;align-items:center;gap:12px"><span class="avatar">'+esc(s.name.slice(0,1))+'</span><div><div class="eyebrow">STUDENT REPORT</div><h2 style="margin-top:6px">'+esc(s.name)+' <span style="font-size:14px;font-weight:400">개인별 리포트</span></h2><span class="pill">'+esc(s.class)+'</span></div></div><button class="btn light small no-print" data-click="openEditor(\'students\',\''+esc(s.id)+'\')">학생 정보 수정</button></div><div class="report-meta"><span>'+esc(s.school)+' · '+esc(s.grade)+'</span><span>소속 학원 '+esc(s.academy||'미입력')+'</span><span>학생 '+esc(s.phone)+'</span><span>학부모 '+esc(s.parentPhone||'미입력')+'</span></div></div><div class="toolbar report-toolbar"><label>조회 시작일<input type="date" value="'+esc(reportStart)+'" data-change="setReportDate(\'start\',this.value)"></label><label>조회 종료일<input type="date" value="'+esc(reportEnd)+'" data-change="setReportDate(\'end\',this.value)"></label><button class="btn light small" data-click="setPeriod(\'month\')">이번 달</button><button class="btn light small" data-click="setPeriod(\'all\')">전체 기간</button></div><div class="report-info">'+(reportStart||reportEnd?esc((reportStart||'처음')+' ~ '+(reportEnd||'현재까지의 전체 기록')):'전체 기간의 기록')+' · 저장된 기록 기준</div><div class="report-tabs" role="tablist" aria-label="리포트 항목">'+reportTabs.map(([k,n])=>'<button role="tab" aria-selected="'+(reportTab===k)+'" class="'+(reportTab===k?'active':'')+'" data-click="setReportTab(\''+k+'\')">'+n+'</button>').join('')+'</div><div class="report-content" id="report-content"></div><footer>데이터는 이 브라우저에 저장됩니다.</footer>';
if(reportStart&&reportEnd&&reportStart>reportEnd){$('#report-content').innerHTML='<div class="note">조회 종료일을 시작일 이후로 선택해 주세요.</div>';return}
const empty=t=>'<div class="report-empty">'+t+'</div>',stat=(label,value,unit,detail)=>'<div class="card"><div class="stat-label">'+label+'</div><div class="report-stat">'+(value??'—')+'<small style="font-size:13px;font-weight:400"> '+unit+'</small></div><div class="tiny">'+detail+'</div></div>';
let html='';if(reportTab==='overview'){const late=d.tasks.filter(t=>t.date<today()&&!taskSubmitted(t,s.id));html='<div class="stats">'+stat('출석률',d.rate,d.rate===null?'':'%',d.counted.length?'기록 '+d.counted.length+'회 중 출석 '+d.present+'회':'출결 기록 없음')+stat('과제 제출률',d.taskRate,d.taskRate===null?'':'%',d.tasks.length?'총 '+d.tasks.length+'개 중 '+d.submitted+'개 제출':'배부된 과제 없음')+stat('평균 성적',d.average,d.average===null?'':'점',d.scores.length+'회 평가 · 100점 만점')+stat('미제출 과제',d.taskCounts.missing,'개','제출 대기 '+(d.taskCounts.pending+d.taskCounts.overdue)+'개 · 기한 지난 과제 '+late.length+'개')+'</div><div class="grid"><div class="card"><div class="row"><h3>자동 학습 요약</h3><button class="btn light small" data-click="setReportTab(\'tasks\')">과제 확인 ↗</button></div><div class="note">'+(late.length?'마감이 지난 미제출 과제가 <b>'+late.length+'개</b> 있습니다.':'마감이 지난 미제출 과제가 없습니다.')+'<br>과제 정시제출 '+d.taskCounts.ontime+'개 · 지각제출 '+d.taskCounts.late+'개 · 미제출 '+d.taskCounts.missing+'개 · 미흡 '+d.taskCounts.insufficient+'개<br>출결 지각 '+d.counted.filter(x=>x.status==='지각').length+'회 · 결석 '+d.counted.filter(x=>x.status==='결석').length+'회</div><details class="report-info calculation-note"><summary>집계 기준 보기</summary>출석률 = 출석·지각 ÷ 기록된 출결(오늘까지). 미기록 날짜는 계산에서 제외합니다.<br>과제는 배부 대상과 마감일을 기준으로 집계합니다. 제출률에는 정시제출·지각제출·미흡을 포함하며, 미흡은 보완이 필요한 과제입니다.</details></div><div class="card"><div class="row"><h3>성적 흐름</h3><button class="btn light small" data-click="setReportTab(\'scores\')">상세 보기 ↗</button></div>'+scoreChart(d.scores,empty)+'</div></div><div class="card bottom"><div class="row"><h3>최근 상담 · 피드백</h3><button class="btn light small" data-click="reportEdit(\'notes\')">＋ 상담 기록</button></div>'+(d.notes.length?d.notes.slice(0,3).map(n=>'<div class="classrow"><div class="classbody"><strong>'+esc(n.type)+' <small>'+esc(n.date)+'</small></strong><div class="wrap-text">'+esc(n.memo)+'</div></div></div>').join(''):empty('아직 상담 기록이 없습니다.'))+'</div>';}
if(reportTab==='attendance')html='<div class="note">기록 '+d.attendance.length+'회 · 출석 '+d.attendance.filter(x=>x.status==='출석').length+'회 · 지각 '+d.attendance.filter(x=>x.status==='지각').length+'회 · 결석 '+d.attendance.filter(x=>x.status==='결석').length+'회</div><div class="toolbar"><button class="btn light" data-click="go(\'attendance\')">출결 관리에서 새 날짜 기록</button></div>'+table(['날짜','상태','출결 수정'],d.attendance.map(x=>[esc(x.date),badge(x.status),'<select aria-label="'+esc(x.date)+' 출결 수정" data-date="'+esc(x.date)+'" data-change="reportAtt(this.dataset.date,this.value)">'+options(['미기록','출석','지각','결석'],x.status)+'</select>']));
if(reportTab==='tasks')html='<div class="note">배부 '+d.tasks.length+'개 · 제출 '+d.submitted+'개. 제출에는 정시제출·지각제출·미흡을 포함합니다. 상태 변경은 과제 관리와 리포트에 함께 반영됩니다.</div>'+taskStatusSummary(d.tasks.map(t=>taskStatus(t,s.id)))+table(['과제명','수업','마감일','제출 상태 · 눌러서 변경'],d.tasks.map(t=>[esc(t.title),esc(t.class),esc(t.date),taskStatusControl(t,s.id)]));
if(reportTab==='scores')html='<div class="row bottom"><h3>평가 기록</h3><button class="btn" data-click="reportEdit(\'scores\')">＋ 성적 입력</button></div><div class="card bottom">'+scoreChart(d.scores,empty)+'</div><div class="bottom">'+table(['평가일','평가명','점수'],d.scores.slice().reverse().map(x=>[esc(x.date),esc(x.title),'<b>'+esc(x.score)+'</b> / 100']))+'</div>';
if(reportTab==='notes')html='<div class="row bottom"><h3>상담 기록</h3><button class="btn" data-click="reportEdit(\'notes\')">＋ 상담 기록</button></div><div class="bottom">'+table(['날짜','유형','상담 내용'],d.notes.map(x=>[esc(x.date),badge(x.type),'<div class="wrap-text">'+esc(x.memo)+'</div>']))+'</div>';
if(reportTab==='bookings')html='<div class="row bottom"><h3>직접 입력한 클리닉 기록</h3><button class="btn" data-click="reportEdit(\'bookings\')">＋ 기록 추가</button></div><div class="bottom">'+table(['예약 일시','피드백 내용','상태'],d.bookings.map(x=>[esc(x.date+' '+x.time),'<div class="wrap-text">'+esc(x.memo)+'</div>','<select aria-label="클리닉 예약 상태" data-id="'+esc(x.id)+'" data-change="reportStatus(\'bookings\',this.dataset.id,this.value)">'+options(['예약','완료','취소'],x.status)+'</select>']))+'</div>';
if(reportTab==='payments')html='<div class="row bottom"><h3>수납 내역</h3><button class="btn" data-click="reportEdit(\'payments\')">＋ 수납 등록</button></div><div class="note">미납 합계 '+d.unpaid.toLocaleString()+'원 · 실제 결제 기능이 아닌 수기 기록입니다.</div>'+table(['청구월','금액','상태'],d.payments.map(x=>[esc(x.month),Number(x.amount).toLocaleString()+'원','<select aria-label="수납 상태" data-id="'+esc(x.id)+'" data-change="reportStatus(\'payments\',this.dataset.id,this.value)">'+options(['미납','완료'],x.status)+'</select>']));
$('#report-content').innerHTML=html;if(typeof enhanceStudentReport==='function')enhanceStudentReport(d);if(typeof enhanceWeeklyStudentReport==='function')enhanceWeeklyStudentReport(d);}
function scoreChart(scores,empty){if(!scores.length)return empty('아직 평가 기록이 없습니다.');const latest=scores.slice(-8);return '<div class="report-chart" role="img" aria-label="최근 '+latest.length+'회 성적: '+esc(latest.map(x=>x.title+' '+x.score+'점').join(', '))+'">'+latest.map(x=>'<div class="report-bar" title="'+esc(x.title+' · '+x.date)+'"><small>'+esc(x.score)+'</small><i style="height:'+Math.max(1,Number(x.score))+'px"></i><small class="tiny">'+esc(x.date.slice(5))+'</small></div>').join('')+'</div><div class="report-info">최근 최대 8회 평가 · 100점 만점 · 날짜순</div>'}
function initReport(){let changed=false;db.tasks.forEach(t=>{if(!Array.isArray(t.studentIds)){t.studentIds=[...new Set([...sortedStudents(db.students).filter(s=>s.class===t.class).map(s=>s.id),...(t.done||[])])];changed=true}});if(changed&&!invalidStoredData)save();if(location.hash.startsWith('#student/')){reportStudent=readStudentHash();page='report'}render()}
window.addEventListener('popstate',()=>{if(location.hash.startsWith('#student/')){reportStudent=readStudentHash();page='report'}else page='students';render()});

function backup(){let a=document.createElement('a');let url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.href=url;a.download='yensense-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}async function restore(input){try{if(!input.files?.[0]||input.files[0].size>MAX_BACKUP_BYTES)throw Error();let v=JSON.parse(await input.files[0].text());v=validateDatabase(v);if(!confirm('백업 파일의 데이터로 현재 기록을 교체할까요?'))return;db=v;invalidStoredData=false;save();initReport();toast('백업을 복원했습니다')}catch{toast('올바른 옌쌤 백업 JSON 파일인지 확인해 주세요')}input.value=''}function classAcademyField(c){const names=[...new Set([...db.classes.map(c=>c.academy),...db.students.map(s=>s.academy)].map(v=>String(v||'').trim()).filter(Boolean))].sort(studentNameCollator.compare);return '<label>배정 학원 (선택)<input name="academy" list="class-academy-options" maxlength="80" value="'+esc(c.academy||'')+'" placeholder="학원 선택 또는 새 학원명 입력"><datalist id="class-academy-options">'+names.map(n=>'<option value="'+esc(n)+'"></option>').join('')+'</datalist><small>월별 정산의 학원으로 자동 연동됩니다. 최초 배정은 기존 출결에도 반영되며, 이후 변경은 새 출결부터 적용됩니다.</small></label>'}
function applyInitialClassAcademy(classId,academy){for(const rows of Object.values(db.attendanceAssignments||{}))for(const record of Object.values(rows))if(record.classId===classId)record.academy=academy}
let dashboardCalendarDate=today(),attendanceClassId='';
function calendarDateValid(date){return /^\d{4}-\d{2}-\d{2}$/.test(date)&&Number.isFinite(Date.parse(date+'T12:00:00Z'))&&new Date(date+'T12:00:00Z').toISOString().slice(0,10)===date}
function calendarAdd(date,days){return new Date(Date.parse(date+'T12:00:00Z')+days*86400000).toISOString().slice(0,10)}
function calendarWeek(date){const index=(new Date(date+'T12:00:00Z').getUTCDay()+6)%7,start=calendarAdd(date,-index);return Array.from({length:7},(_,i)=>calendarAdd(start,i))}
function scheduledClasses(date){if(!calendarDateValid(date))return [];const day=['일','월','화','수','목','금','토'][new Date(date+'T12:00:00Z').getUTCDay()];return formalClasses().filter(c=>c.day===day).sort(compareSchedules)}
function attendanceStudents(date=attDate,classId=attendanceClassId,search=query){const classes=scheduledClasses(date).filter(c=>!classId||c.id===classId),ids=new Set(classes.map(c=>c.id)),names=new Set(classes.map(c=>c.name));return sortedStudents(currentStudents()).filter(s=>{const captured=db.attendanceAssignments?.[date]?.[s.id];const assigned=captured?.classId?ids.has(captured.classId):names.has(s.class);return assigned&&[s.name,s.school,s.academy||'',s.class,s.grade,s.group||''].some(v=>v.toLocaleLowerCase('ko').includes(search.toLocaleLowerCase('ko')))})}
function setCalendarDate(el){if(!calendarDateValid(el.value))return;attDate=el.value;dashboardCalendarDate=el.value;if(!scheduledClasses(attDate).some(c=>c.id===attendanceClassId))attendanceClassId='';render()}
function shiftCalendar(direction){const date=page==='attendance'?attDate:dashboardCalendarDate,next=direction==='today'?today():calendarAdd(date,direction==='previous'?-7:7);setCalendarDate({value:next})}
function selectAttendanceClass(id){attendanceClassId=scheduledClasses(attDate).some(c=>c.id===id)?id:'';drawRows()}
function openClassAttendance(id,date){if(!calendarDateValid(date)||!scheduledClasses(date).some(c=>c.id===id))return;attDate=date;dashboardCalendarDate=date;attendanceClassId=id;query='';filter='';page='attendance';render();$('#attendance-roster')?.scrollIntoView({block:'start',behavior:'smooth'})}
function renderAttendancePage(view){if(!scheduledClasses(attDate).some(c=>c.id===attendanceClassId))attendanceClassId='';view.innerHTML=dashboardTimetable()+'<section id="attendance-roster" class="card bottom"><div class="row"><div><h3>수업별 출결</h3><p class="tiny">선택한 날짜에 수업이 있는 학생만 표시합니다. 캘린더에서 수업을 누르면 해당 수업만 열립니다.</p></div><span class="pill">'+esc(attDate)+'</span></div><div class="toolbar attendance-controls"><label>학생 검색<input aria-label="검색" value="'+esc(query)+'" placeholder="이름·학교 검색" data-input="query=this.value;drawRows()"></label><label>해당 날짜 수업<select aria-label="출결 수업" data-change="selectAttendanceClass(this.value)"><option value="">해당 날짜 전체 수업</option>'+scheduledClasses(attDate).map(c=>'<option value="'+esc(c.id)+'" '+(attendanceClassId===c.id?'selected':'')+'>'+esc(c.time+' · '+c.name)+'</option>').join('')+'</select></label><button class="btn light" data-click="allPresent()">조회 학생 전체 출석</button></div><div id="rows"></div></section>';drawRows()}
function attendanceRoster(){const classes=scheduledClasses(attDate),selected=classes.find(c=>c.id===attendanceClassId),students=attendanceStudents();if(!classes.length)return '<div class="empty">'+esc(attDate)+'에는 등록된 정식 수업이 없습니다.</div>';return '<div class="attendance-context" role="status"><b>'+esc(selected?selected.name:'해당 날짜 전체 수업')+'</b><span>'+students.length+'명 · '+esc(attDate)+(selected?' · '+esc(selected.time+'–'+selected.end):'')+'</span></div>'+table(['학생','수강 수업','출결 상태'],students.map(s=>{const captured=db.attendanceAssignments?.[attDate]?.[s.id];return [studentLink(s),esc(captured?.className||s.class),'<select aria-label="'+esc(s.name)+' 출결" data-change="setAtt(\''+s.id+'\',this.value)">'+options(['미기록','출석','지각','결석'],attendanceStatus((db.attendance[attDate]||{})[s.id])||'미기록')+'</select>']}))}

function timetableLayout(classes){const minutes=t=>Number(t.slice(0,2))*60+Number(t.slice(3));const start=classes.length?Math.min(...classes.map(c=>Math.floor(minutes(c.time)/60)*60)):9*60,end=classes.length?Math.max(...classes.map(c=>Math.ceil(minutes(c.end)/60)*60)):22*60;const days=['월','화','수','목','금','토','일'].map(day=>{const items=classes.filter(c=>c.day===day).sort(compareSchedules),clusters=[];for(const c of items){let cluster=clusters.at(-1);if(!cluster||minutes(c.time)>=Math.max(...cluster.map(x=>minutes(x.end))))clusters.push(cluster=[]);cluster.push(c)}return clusters.flatMap(cluster=>{const ends=[],placed=cluster.map(c=>{let col=ends.findIndex(end=>end<=minutes(c.time));if(col<0){col=ends.length;ends.push(0)}ends[col]=minutes(c.end);return {...c,column:col,top:minutes(c.time)-start,height:minutes(c.end)-minutes(c.time)}});return placed.map(c=>({...c,columns:ends.length}))})});return {start,end,days}}
function dashboardTimetable(){const anchor=page==='attendance'?attDate:dashboardCalendarDate,dates=calendarWeek(anchor),classes=formalClasses(),layout=timetableLayout(classes),days=['월','화','수','목','금','토','일'],hour=n=>String(Math.floor(n/60)).padStart(2,'0')+':00';return '<section class="card dashboard-timetable bottom"><div class="row"><div><h3>주간 수업 타임테이블</h3><p class="tiny">정식 수업 '+classes.length+'개 · 월요일부터 시간순 · 수업을 누르면 해당 날짜·수업의 출결 명단이 열립니다.</p></div><button class="btn light small" data-click="go(\'classes\')">수업 관리 ↗</button></div><div class="calendar-week-tools"><button class="btn light small" aria-label="이전 주" data-click="shiftCalendar(\'previous\')">‹ 이전 주</button><label>기준 날짜<input aria-label="캘린더 기준 날짜" type="date" value="'+esc(anchor)+'" data-change="setCalendarDate(this)"></label><button class="btn light small" aria-label="다음 주" data-click="shiftCalendar(\'next\')">다음 주 ›</button><button class="btn light small" data-click="shiftCalendar(\'today\')">오늘</button><span class="tiny">'+esc(dates[0]+' ~ '+dates[6])+'</span></div>'+(!classes.length?'<div class="empty">등록된 수업이 없습니다. 수업 관리에서 수업을 등록해 주세요.</div>':'<p class="tiny timetable-mobile-hint">좌우로 밀어 요일별 수업을 확인하세요.</p><div class="timetable-scroll" tabindex="0" aria-label="월요일부터 일요일까지 주간 수업 타임테이블"><div class="timetable-head"><span>시간</span>'+days.map((day,i)=>'<b class="'+(dates[i]===today()?'calendar-today ':'')+(dates[i]===anchor?'calendar-selected':'')+'">'+day+'요일<small>'+dates[i].slice(5).replace('-','/')+'</small></b>').join('')+'</div><div class="timetable-body" style="height:'+(layout.end-layout.start)+'px"><div class="timetable-axis">'+Array.from({length:(layout.end-layout.start)/60+1},(_,i)=>'<span style="top:'+(i*60)+'px">'+hour(layout.start+i*60)+'</span>').join('')+'</div>'+layout.days.map((items,i)=>'<div class="timetable-day" aria-label="'+days[i]+'요일">'+items.map(c=>{const label=[c.name,dates[i]+' '+days[i]+'요일',c.time+'–'+c.end,c.academy||'학원 미배정',c.room].join(' · ');return '<button class="timetable-event timetable-color-'+i+'" style="top:'+c.top+'px;height:'+c.height+'px;left:calc('+c.column/c.columns*100+'% + 3px);width:calc('+100/c.columns+'% - 6px)" title="'+esc(label)+'" aria-label="'+esc(label)+' 출결 확인" data-id="'+esc(c.id)+'" data-date="'+dates[i]+'" data-click="openClassAttendance(this.dataset.id,this.dataset.date)"><span class="timetable-event-time">'+esc(c.time+'–'+c.end)+'</span><strong>'+esc(c.name)+'</strong><span>'+esc(c.academy||'학원 미배정')+'</span><small>'+esc(c.room)+'</small></button>'}).join('')+'</div>').join('')+'</div></div>')+'</section>'}
function openQuickExamRegistration(){selectedExamId='';go('exams');const input=$('#exam-form input[name=title]');if(input){input.scrollIntoView({block:'center',behavior:'smooth'});input.focus()}}

function compareSchedules(a,b){const days=['월','화','수','목','금','토','일'];return days.indexOf(a.day)-days.indexOf(b.day)||String(a.time||'').localeCompare(String(b.time||''))||studentNameCollator.compare(a.name||a.title||'',b.name||b.title||'')}
let settlementMonth=today().slice(0,7),settlementAcademy='',settlementClass='';
function captureAttendanceAssignment(date,id,inferred=false){const s=db.students.find(s=>s.id===id);if(!s)return;db.attendanceAssignments??={};db.attendanceAssignments[date]??={};if(!db.attendanceAssignments[date][id]){const c=formalClasses().find(c=>c.name===s.class);db.attendanceAssignments[date][id]={classId:c?.id||'',className:c?.name||'',academy:c?.academy?.trim()||s.academy?.trim()||'학원 미지정',inferred}}}
function snapshotAttendanceAssignments(){for(const [date,rows] of Object.entries(db.attendance))for(const id of Object.keys(rows))captureAttendanceAssignment(date,id,true)}
function settlementEntries(month){const rows=[];for(const [date,entries] of Object.entries(db.attendance)){if(!date.startsWith(month+'-')||date>today())continue;for(const [id,status] of Object.entries(entries)){if(attendanceStatus(status)!=='출석')continue;const s=db.students.find(s=>s.id===id);if(!s)continue;const captured=db.attendanceAssignments?.[date]?.[id],c=formalClasses().find(c=>c.name===s.class),assignment=captured||{classId:c?.id||'',className:c?.name||'',academy:c?.academy?.trim()||s.academy?.trim()||'학원 미지정'};if(!assignment.classId)continue;rows.push({date,studentId:id,name:s.name,...assignment,inferred:!captured||!!captured.inferred})}}return rows.sort((a,b)=>a.date.localeCompare(b.date)||studentNameCollator.compare(a.name,b.name))}
function settlementRule(month,academy,classId){const rules=db.settlementRules||[];return rules.find(r=>r.month===month&&r.academy===academy&&r.classId===classId)||rules.find(r=>r.month===month&&r.academy===academy&&!r.classId)||null}
function settlementGroups(month){const map=new Map();for(const c of formalClasses()){if(c.academy?.trim()){const academy=c.academy.trim();map.set(JSON.stringify([academy,c.id]),{academy,classId:c.id,className:c.name,entries:[]})}}for(const s of db.students){const c=formalClasses().find(c=>c.name===s.class);if(c){const academy=c.academy?.trim()||s.academy?.trim()||'학원 미지정',key=JSON.stringify([academy,c.id]);if(!map.has(key))map.set(key,{academy,classId:c.id,className:c.name,entries:[]})}}for(const e of settlementEntries(month)){const key=JSON.stringify([e.academy,e.classId]);if(!map.has(key))map.set(key,{academy:e.academy,classId:e.classId,className:e.className,entries:[]});map.get(key).entries.push(e)}return [...map.values()].sort((a,b)=>studentNameCollator.compare(a.academy,b.academy)||studentNameCollator.compare(a.className,b.className)).map(g=>{const rule=settlementRule(month,g.academy,g.classId),tickets=g.entries.length,gross=rule?tickets*Number(rule.unit):null,amount=rule?Math.round(gross*Number(rule.rate)/100):null;return {...g,rule,tickets,gross,amount}})}
function setSettlementField(el){if(el.name==='month'&&!/^\d{4}-(0[1-9]|1[0-2])$/.test(el.value))return;if(el.name==='month')settlementMonth=el.value;if(el.name==='academy')settlementAcademy=el.value;if(el.name==='classId')settlementClass=el.value;renderSettlements($('#view'))}
function renderSettlements(view){const all=settlementGroups(settlementMonth),rows=all.filter(g=>(!settlementAcademy||g.academy===settlementAcademy)&&(!settlementClass||g.classId===settlementClass)),academies=[...new Set(all.map(g=>g.academy))].sort(studentNameCollator.compare),money=v=>v===null?'미설정':Number(v).toLocaleString()+'원';view.innerHTML='<section class="card bottom settlement-filters"><label>정산월<input type="month" name="month" value="'+esc(settlementMonth)+'" data-change="setSettlementField(this)"></label><label>학원<select name="academy" data-change="setSettlementField(this)"><option value="">전체 학원</option>'+options(academies,settlementAcademy)+'</select></label><label>수업<select name="classId" data-change="setSettlementField(this)"><option value="">전체 수업</option>'+formalClasses().map(c=>'<option value="'+esc(c.id)+'" '+(c.id===settlementClass?'selected':'')+'>'+esc(c.name)+'</option>').join('')+'</select></label><button class="btn" data-click="editSettlementRule()">단가 · 정산 비율 설정</button></section><div class="note">출석 1회 = 티켓 1장 · 지각·결석·미기록 및 미래 날짜는 제외합니다. 정산액 = 티켓 수 × 단가 × 강사 정산 비율 (원 단위 반올림). 수업별 설정이 학원 기본 설정보다 우선하며, 설정은 선택한 월에만 적용됩니다. 수업에 배정한 학원이 정산에 우선 적용됩니다. 학원 최초 배정은 기존 출결에도 반영되며, 이후 학원 변경은 새 출결부터 적용됩니다.</div><div class="stats">'+[['출석 티켓',rows.reduce((n,g)=>n+g.tickets,0)+'장'],['총 수업 금액',money(rows.reduce((n,g)=>n+(g.gross||0),0))],['강사 정산액',money(rows.reduce((n,g)=>n+(g.amount||0),0))],['설정 필요',rows.filter(g=>!g.rule).length+'개 수업']].map(([k,v])=>'<div class="card"><div class="stat-label">'+k+'</div><div class="stat-num" style="font-size:24px">'+v+'</div></div>').join('')+'</div><section class="bottom"><h3>학원별 정산 합계</h3>'+table(['학원','티켓','강사 정산액'],[...new Set(rows.map(g=>g.academy))].map(a=>{const gs=rows.filter(g=>g.academy===a);return [esc(a),gs.reduce((n,g)=>n+g.tickets,0)+'장',money(gs.reduce((n,g)=>n+(g.amount||0),0))+(gs.some(g=>!g.rule)?' · 미설정 제외':'')]}))+'</section><section class="bottom"><h3>수업별 정산 현황</h3>'+table(['학원','수업','출석 티켓','티켓 단가','강사 비율','총 수업 금액','강사 정산액'],rows.map(g=>[esc(g.academy),esc(g.className),g.tickets+'장',g.rule?money(g.rule.unit):'미설정',g.rule?g.rule.rate+'%'+(g.rule.classId?' · 수업별':' · 학원 기본'):'미설정',money(g.gross),money(g.amount)]))+'</section><details class="card bottom"><summary>출석 티켓 상세 내역</summary><p class="tiny">수업에 배정한 학원을 우선 사용하며, 수업 학원이 없으면 학생의 소속 학원을 사용합니다. 기존 출결은 현재 배정을 기준으로 추정합니다. 이후 수업 배정 변경 시 기존 기록의 소속을 보존합니다. 수업 미배정 기록은 정산에서 제외됩니다. 동일 학생의 동일 날짜는 1장으로 계산합니다.</p>'+table(['날짜','학생','학원','수업','티켓','소속 기준'],rows.flatMap(g=>g.entries).sort((a,b)=>a.date.localeCompare(b.date)||studentNameCollator.compare(a.name,b.name)).map(e=>[esc(e.date),esc(e.name),esc(e.academy),esc(e.className),'1장',e.inferred?'현재 배정 기준':'기록 당시 배정']))+'</details><p class="tiny">설정·출결은 이 브라우저에 저장되며 JSON 백업에 함께 포함됩니다. 미설정 수업은 합계에서 제외됩니다.</p>'}
function editSettlementRule(){const academies=[...new Set(settlementGroups(settlementMonth).map(g=>g.academy))];if(!academies.length)return toast('학생의 소속 학원과 정식 수업을 먼저 등록해 주세요.');$('#modal').innerHTML='<h2>단가 · 강사 정산 비율</h2><p>'+esc(settlementMonth)+'에 적용됩니다. 학원 기본값을 설정하고 필요한 수업만 별도로 조정하세요.</p><form id="settlement-rule"><div class="fields"><label>학원<select name="academy">'+options(academies,settlementAcademy)+'</select></label><label>적용 범위<select name="classId"><option value="">학원 전체 기본값</option>'+formalClasses().map(c=>'<option value="'+esc(c.id)+'">'+esc(c.name)+'</option>').join('')+'</select></label><label>티켓 1장 단가 (원)<input required name="unit" type="number" min="0" max="1000000000" step="1"></label><label>강사 정산 비율 (%)<input required name="rate" type="number" min="0" max="100" step="0.01"></label></div><p id="settlement-rule-hint" class="tiny"></p><div class="actions"><button type="button" class="btn light" data-click="resetSettlementRule()">해당 설정 해제</button><button type="button" class="btn light" data-click="document.getElementById(\'modal\').close()">취소</button><button class="btn">저장</button></div></form>';const form=$('#settlement-rule');const update=()=>{const rule=(db.settlementRules||[]).find(r=>r.month===settlementMonth&&r.academy===form.elements.academy.value&&r.classId===form.elements.classId.value);form.elements.unit.value=rule?.unit??'';form.elements.rate.value=rule?.rate??'';$('#settlement-rule-hint').textContent=rule?'저장된 설정을 수정합니다.':'새 설정입니다. 학원 미지정 학생은 「학원 미지정」으로 계산합니다.'};form.elements.academy.addEventListener('change',update);form.elements.classId.addEventListener('change',update);update();form.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(form)),unit=Number(v.unit),rate=Number(v.rate);if(!Number.isSafeInteger(unit)||unit<0||unit>1e9||!Number.isFinite(rate)||rate<0||rate>100)return toast('단가와 비율을 확인해 주세요.');db.settlementRules=(db.settlementRules||[]).filter(r=>!(r.month===settlementMonth&&r.academy===v.academy&&r.classId===v.classId));db.settlementRules.push({month:settlementMonth,academy:v.academy,classId:v.classId,unit,rate});save();$('#modal').close();renderSettlements($('#view'));toast('월별 정산 설정을 저장했습니다')};$('#modal').showModal()}
function resetSettlementRule(){const f=$('#settlement-rule');db.settlementRules=(db.settlementRules||[]).filter(r=>!(r.month===settlementMonth&&r.academy===f.elements.academy.value&&r.classId===f.elements.classId.value));save();$('#modal').close();renderSettlements($('#view'));toast('설정을 해제했습니다')}

// Shared selection for rendered record lists. Existing student/booking selection stays authoritative.
function installListSelection(root=document){
 const state=new WeakMap();
 const labelOf=row=>String(row.getAttribute('data-bulk-label')||row.querySelector('strong,h3,h4,b')?.textContent||row.textContent||'항목').trim().replace(/\s+/g,' ').slice(0,100);
 function controls(container,items,table){const old=state.get(container);if(old){if(old.items.length===items.length&&old.items.every((item,i)=>item===items[i])&&old.boxes.every(box=>box.isConnected))return;old.bar.remove();for(const box of old.boxes){const holder=box.closest('td,.universal-card-check');holder?.remove()}container.querySelector('thead .universal-all')?.closest('th')?.remove();state.delete(container)}if(!items.length||items.some(item=>item.querySelector(table?'input[type=checkbox]':'input.student-select,input[data-change^=toggleWeeklyStudent]')))return;const boxes=[],bar=document.createElement('div'),count=document.createElement('span'),clear=document.createElement('button'),all=document.createElement('input'),label=document.createElement('label');bar.className='universal-selection-bar no-print';all.type='checkbox';all.setAttribute('aria-label','현재 목록 전체 선택');label.append(all,document.createTextNode(' 현재 목록 전체 선택'));clear.type='button';clear.className='btn light small';clear.textContent='선택 해제';count.setAttribute('aria-live','polite');table?bar.append(count):bar.append(label,count);const sync=()=>{const n=boxes.filter(b=>b.checked).length;all.checked=n===boxes.length&&n>0;all.indeterminate=n>0&&n<boxes.length;count.textContent=n+' / '+boxes.length+'개 선택';clear.disabled=!n;if(table)bar.hidden=!n;boxes.forEach(b=>b.closest('tr,.universal-selectable-item')?.classList.toggle('universal-selected',b.checked));if(table){const header=container.querySelector('thead input.universal-all');if(header){header.checked=all.checked;header.indeterminate=all.indeterminate}}};const select=value=>{boxes.forEach(b=>b.checked=value);sync()};all.addEventListener('change',()=>select(all.checked));clear.addEventListener('click',()=>select(false));
 if(table){const heading=document.createElement('th'),header=document.createElement('input');header.type='checkbox';header.className='universal-all';header.setAttribute('aria-label','현재 목록 전체 선택');header.addEventListener('change',()=>select(header.checked));heading.className='no-print';heading.append(header);container.tHead.rows[0].prepend(heading);const wrap=container.closest('.tablewrap')||container;wrap.before(bar)}else items[0].before(bar);
 for(const [i,item] of items.entries()){const box=document.createElement('input');box.type='checkbox';box.className='universal-row-select';box.setAttribute('aria-label',labelOf(item)+' 선택');box.addEventListener('change',sync);boxes.push(box);if(table){const cell=document.createElement('td');cell.className='no-print';cell.append(box);item.prepend(cell)}else{item.classList.add('universal-selectable-item');const holder=document.createElement('label');holder.className='universal-card-check';holder.append(box,document.createTextNode('선택'));item.prepend(holder)}}state.set(container,{bar,boxes,items});sync()}
 function scan(){for(const table of root.querySelectorAll('table')){const rows=[...table.tBodies].flatMap(body=>[...body.rows]).filter(row=>row.cells.length>1);controls(table,rows,true)}const groups=new Map();for(const item of root.querySelectorAll('#rows > .card.bottom,#review-video-list > article,#integration-content .feature-columns > .card:last-child > .question-card,.task-students > .task-student,.card > .classrow,.card > .taskline,#exam-question-editor > .question-card,#review-quiz-questions > .review-quiz-question')){const parent=item.parentElement;if(!groups.has(parent))groups.set(parent,[]);groups.get(parent).push(item)}for(const [parent,items] of groups){controls(parent,items,false)}}
 function nativeGroup(group){if(state.has(group))return;const boxes=[...group.querySelectorAll('input[type=checkbox]')];if(!boxes.length)return;const bar=document.createElement('div'),label=document.createElement('label'),all=document.createElement('input'),count=document.createElement('span'),clear=document.createElement('button');bar.className='universal-selection-bar no-print';all.type='checkbox';all.setAttribute('aria-label','현재 목록 전체 선택');label.append(all,document.createTextNode(' 현재 목록 전체 선택'));clear.type='button';clear.className='btn light small';clear.textContent='선택 해제';bar.append(label,count);const sync=()=>{const n=boxes.filter(b=>b.checked).length;all.checked=n===boxes.length;all.indeterminate=n>0&&n<boxes.length;count.textContent=n+' / '+boxes.length+'개 선택';clear.disabled=!n};const choose=checked=>{if(boxes.every(box=>box.disabled))return;if(group.matches('.weekly-roster,.weekly-checks')&&weeklyState.busy)return;if(group.matches('.weekly-roster')){weeklyState.excluded=checked?[]:weeklyStudents().map(s=>s.id);renderWeeklyReports();return}if(group.matches('.weekly-checks')){if(group.closest('fieldset')?.querySelector('legend')?.textContent.includes('수신'))weeklyState.recipients=checked?['parent','student']:[];else weeklyState.sections=checked?Object.keys(weeklySections):[];renderWeeklyReports();return}for(const box of boxes){if(box.disabled)continue;box.checked=checked;box.dispatchEvent(new Event('change',{bubbles:true}))}sync()};all.addEventListener('change',()=>choose(all.checked));clear.addEventListener('click',()=>choose(false));group.addEventListener('change',sync);group.before(bar);state.set(group,{bar,boxes,items:boxes});sync()}
 const scanRecords=scan;scan=function(){scanRecords();for(const group of root.querySelectorAll('.video-audience,.class-review-courses,.weekly-roster,.weekly-checks'))nativeGroup(group)};
 let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;scan()})});observer.observe(root===document?document.body:root,{childList:true,subtree:true});scan();return ()=>observer.disconnect();
}
if(typeof MutationObserver!=='undefined')installListSelection();



let panelStudent='',panelTab='overview',panelReturnFocus=null;
function closeStudentPanel(){document.querySelector('#student-detail-panel')?.remove();document.body.classList.remove('student-panel-open');panelReturnFocus?.focus?.()}
function setStudentPanelTab(tab){panelTab=tab;renderStudentPanel()}
function openStudentPanel(id){if(!db.students.some(s=>s.id===id))return;panelReturnFocus=document.activeElement;panelStudent=id;panelTab='overview';renderStudentPanel()}
function renderStudentPanel(){
 document.querySelector('#student-detail-panel')?.remove();const d=reportData(panelStudent,{start:'',end:''});if(!d)return;const s=d.s;
 const tabs=[['overview','기본 정보'],['attendance','출결'],['scores','성적'],['tasks','과제'],['notes','상담']];
 let body='';const empty='<p class="detail-empty">저장된 기록이 없습니다.</p>';
 if(panelTab==='overview')body='<dl class="detail-profile">'+[['학교·학년',s.school+' · '+s.grade],['정식 강좌',s.class||'미배정'],['학생 연락처',s.phone||'미입력'],['학부모 연락처',s.parentPhone||'미입력'],['닉네임',s.nickname||'미지정'],['소속 학원',s.academy||'미입력']].map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><div class="detail-metrics"><div>출석률<strong>'+esc(d.rate??'—')+'%</strong></div><div>평균 성적<strong>'+esc(d.average??'—')+'</strong></div><div>과제 제출<strong>'+d.submitted+'/'+d.tasks.length+'</strong></div></div>';
 if(panelTab==='attendance')body=d.attendance.length?table(['날짜','출결'],d.attendance.slice().reverse().map(x=>[esc(x.date),badge(x.status)])):empty;
 if(panelTab==='scores')body=d.scores.length?table(['날짜','평가','점수'],d.scores.slice().reverse().map(x=>[esc(x.date),esc(x.title),esc(x.score)+'점'])):empty;
 if(panelTab==='tasks')body=d.tasks.length?table(['기한','과제','상태'],d.tasks.slice().reverse().map(x=>[esc(x.date),esc(x.title),esc(taskStates[taskStatus(x,s.id)]?.label||'확인 필요')])):empty;
 if(panelTab==='notes')body=d.notes.length?d.notes.slice().reverse().map(x=>'<article class="detail-note"><small>'+esc(x.date)+' · '+esc(x.type)+'</small><p>'+esc(x.memo)+'</p></article>').join(''):empty;
 const el=document.createElement('aside');el.id='student-detail-panel';el.className='student-detail-panel';el.setAttribute('aria-label','학생 상세 정보');el.innerHTML='<header><span>학생 상세 정보</span><button class="btn light small" aria-label="학생 상세 닫기" data-click="closeStudentPanel()">닫기 ×</button></header><div class="detail-heading"><span class="avatar">'+esc(s.name.slice(0,1))+'</span><div><h2>'+enrollmentBadge(s)+esc(s.name)+'</h2><p>'+esc(s.school)+' · '+esc(s.grade)+'</p></div></div><nav aria-label="학생 상세 항목">'+tabs.map(([k,v])=>'<button aria-pressed="'+(panelTab===k)+'" class="'+(panelTab===k?'active':'')+'" data-click="setStudentPanelTab(\''+k+'\')">'+v+'</button>').join('')+'</nav><div class="detail-content">'+body+'</div><footer><button class="btn light small" data-click="editPanelStudent(\''+esc(s.id)+'\')">학생 정보 수정</button><button class="btn small" data-click="reportPanelStudent(\''+esc(s.id)+'\')">전체 리포트 열기 ↗</button></footer>';document.body.appendChild(el);document.body.classList.add('student-panel-open');
}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeStudentPanel()});

function editPanelStudent(id){closeStudentPanel();openEditor('students',id)}
function reportPanelStudent(id){closeStudentPanel();showReport(id)}

function toggleClassRosterAll(checked){selectClassRoster(checked?'all':'none')}
function syncClassRosterAll(){const all=document.querySelector('#roster-all');if(!all)return;const boxes=[...document.querySelectorAll('.class-roster-row')].filter(r=>!r.hidden).map(r=>r.querySelector('input'));const n=boxes.filter(b=>b.checked).length;all.checked=boxes.length>0&&n===boxes.length;all.indeterminate=n>0&&n<boxes.length;all.disabled=!boxes.length}

// Keep the primary search visible; reveal secondary filters on demand.
if(typeof MutationObserver!=='undefined'){
 let uxQueued=false;const arrangeWorkspace=()=>{for(const filters of document.querySelectorAll('.student-directory-filters')){if(filters.dataset.organized)continue;filters.dataset.organized='true';const labels=[...filters.children].filter(x=>x.tagName==='LABEL'&&!x.classList.contains('student-search-field'));if(!labels.length)continue;const details=document.createElement('details'),summary=document.createElement('summary'),body=document.createElement('div');details.className='workspace-filter-drawer';summary.textContent='필터 · 수업 / 그룹 / 재원 상태';body.className='workspace-filter-grid';for(const label of labels){body.appendChild(label);if(label.querySelector('select')?.value)details.open=true}details.append(summary,body);filters.append(details)}};
 new MutationObserver(()=>{if(uxQueued)return;uxQueued=true;queueMicrotask(()=>{uxQueued=false;arrangeWorkspace()})}).observe(document.body,{childList:true,subtree:true});arrangeWorkspace();
}
